char s[MAXN];
int n, a[MAXN], sMin[MAXN], sMax[MAXN]; bool b[MAXN];
void init() {
	for (int i = 1; i <= n; i++) {
		if (s[i] == '0') a[i] = a[i - 1] - 1;
		else a[i] = a[i - 1] + 1;
		if (s[i] == '?') b[i] = true;
	}
	sMin[n + 1] = n + 5;
	for (int i = n; i >= 0; i--)
		sMin[i] = min(sMin[i + 1], a[i]);
}
int work(int limit) {
	int mns = 0;
	for (int i = 1; i <= n; i++) {
		if (s[i] == '?' && sMin[i] - mns - 2 >= limit) {
			b[i] = false;
			mns += 2;
		} 
		a[i] -= mns;
	}
	sMin[n + 1] = n + 5;
	sMax[n + 1] = -n - 5;
	for (int i = n; i >= 0; i--) {
		sMin[i] = min(sMin[i + 1], a[i]);
		sMax[i] = max(sMax[i + 1], a[i]);
	}
	int ans = sMax[0] - sMin[0];
	int Max = 0, Min = 0; mns = 0;
	for (int i = 1; i <= n; i++) {
		if (b[i]) {
			mns -= 2;
			chkmin(ans, max(Max, sMax[i] - mns) - min(Min, sMin[i] - mns));
		}
		a[i] -= mns;
		chkmax(Max, a[i]);
		chkmin(Min, a[i]);
	}
	return ans;
}
int main() {
	scanf("%s", s + 1);
	n = strlen(s + 1);
	int ans = n + 5;
	for (int i = 0; clock() <= 1.5 * CLOCKS_PER_SEC; i++)
		init(), chkmin(ans, work(sMin[0] - i));
	cout << ans << endl;
	return 0;
}

