			int res0 = dpl[0][i] + dpr[0][i + 1];
			int res1 = dpl[1][i] + dpr[1][i + 1];
			if (res0 > res1)S[i] = '0';
			else S[i] = '1';

		}
		int res0 = dpl[0][i] + ((S[i] == '0') ? 1 : -1);
		int res1 = dpl[1][i] + ((S[i] == '1') ? 1 : -1);
		dpl[0][i + 1] = max(0, res0);
		dpl[1][i + 1] = max(0, res1);
		ret2 = max({ ret2,res0,res1 });
	}
	int ret = min(ret1, ret2);
	return ret <= x;
}

int calc(string S) {
	int N = S.size();
	int ans = 0;
	REP(l, N) {
		FOR(r, l + 1, N+1) {
			int c0 = 0, c1 = 0;
			FOR(i, l, r) {
				if (S[i] == '0')c0++;
				else c1++;
			}
			chmax(ans, abs(c0 - c1));
		}
	}
	return ans;
}

int naive(string S) {
	int cnt = 0;
	int N = S.size();
	int mn = S.size();
	vector<int>pos;
	REP(i, N)if (S[i] == '?') {
		pos.push_back(i);
		cnt++;
	}
	REP(bit, 1 << cnt) {
		string s = S;
		REP(i, cnt) {
			if (bit&(1 << i)) {
				s[pos[i]] = '1';
			}
			else s[pos[i]] = '0';
		}
		//DEBUG(s);
		//DEBUG(calc(s));
		mn = min(mn, calc(s));
	}
	//if (cnt == 0)mn = calc(S);
	return mn;
}

int solve_(string s) {
	S = s;
	T = S;
	N = S.size();
	int ok = N, ng = 0;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		//DEBUG(mid);
		if (check(mid)||check2(mid))ok = mid;
		else ng = mid;
	}
	return ok;
}

