pair<int, int> inc(pair<int, int> u, pair<int, int> goodRange) {
    if (u.first == u.second && u.second == goodRange.second) return {1e9, -1e9};
    u.first++;
    u.second++;
    if (u.second > goodRange.second) u.second -= 2;
