pair<int, int> dec(pair<int, int> u, pair<int, int> goodRange) {
    if (u.first == u.second && u.first == goodRange.first) return {1e9, -1e9};
    u.first--;
    u.second--;
    if (u.first < goodRange.first) u.first += 2;
    return u;
