            cur--;
            minVal = min(minVal, cur);
        }
        low = max(low, maxVal - minVal - 1);
    }

    while (high - low > 1) {
        int mid = low + high >> 1;
        if (check(mid)) high = mid;
        else low = mid;
    }
    cout << high << '\n';
}

