bool ps(int dl)
{
	int l = 0, r = 0;
	for (int i = 0; i <= n; i++) {
		int u = (ul - a[i]) / 2, d = (dl - a[i] + 1) / 2;
		if (p[i]) r++;
		l = max(l, d); r = min(r, u);
		if (l > r) return false;
	}
	return true;
}

int bs(int l, int r)
{
	int md = (l + r) / 2;
	if (r == l + 1 && md == l) md = r;
	if (l >= r) return md;
	if (ps(md)) return bs(md, r);
	else return bs(l, md - 1);
}

