int record = 1e9;

unordered_set<unsigned long long> used(1e7);
const unsigned long long ci = 1e12+1e11;
const unsigned long long ca = 1e6+1;

void go(int i, int a, int b) {
    int cand = a + b;
    if (cand >= record) return;
    if (i == n+1) {
        record = cand;
        return;
    }
    unsigned long long h = ci * i + ca * a + b;
    if (!used.insert(h).second) {
        return;
    }
    char c = s[i];
    if (c == '0') {
        if (a == 0) {
            go(i+1, 0, b+1);
        } else {
            go(i+1, a-1, b+1);
        }
    } else if (c == '1') {
        if (b == 0) {
            go(i+1, a+1, 0);
        } else {
            go(i+1, a+1, b-1);
        }
    } else {
        if (a > b) {
            if (a == 0) {
                go(i+1, 0, b+1);
            } else {
                go(i+1, a-1, b+1);
            }
            if (b == 0) {
                go(i+1, a+1, 0);
            } else {
                go(i+1, a+1, b-1);
            }
        } else {
            if (b == 0) {
                go(i+1, a+1, 0);
            } else {
                go(i+1, a+1, b-1);
            }
            if (a == 0) {
                go(i+1, 0, b+1);
            } else {
                go(i+1, a-1, b+1);
            }
        }
    }
}

