using namespace std;
const int N = 1e6+1;
int n, pref[N];
string s;
vi prefv[4*N];
bool solve(int diff) {
	int pos=0, neg=0;
	vi ind(4 * n + 1);
	for(int i=1; i<=n; ++i) {
		if(s[i-1] == '0') {
			pos = max(0, pos-1);
			neg = neg+1;
		}
		else if(s[i-1] == '1') {
			pos = pos+1;
			neg = max(0, neg-1);
		}
		else {
			int j = n+1; // miejsce w którym mamy za dużo '0'
			// neg + (-sum) > diff --> (-sum) > diff - neg --> (-sum) >= diff - neg + 1
			// sum <= neg - diff - 1
			int idx = neg - diff - 1 + pref[i-1] + 2*n;
			if(ind[idx]<(int)prefv[idx].size()) {
				j = prefv[idx][ind[idx]];
			}
			bool fail=0;
			int indx = diff - pos - 1 + pref[i-1] + 2*n;
			if(diff-pos-1<0 || (ind[indx]<(int)prefv[indx].size() && prefv[indx][ind[indx]] < j)) {
				fail = 1;
			}
			if(fail || j==n+1) { // set to 0
				pos = max(0, pos-1);
				neg = neg+1;
			}
			else { // set to 1
				pos = pos+1;
				neg = max(0, neg-1);
			}
		}
		//cerr<<s[i-1]<<' '<<pos<<' '<<neg<<'\n';
		if(pos > diff || neg > diff) return false;
		ind[pref[i]+2*n]++;
	}
	return true;
}
