	ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	cin>>s;
	n = s.size();
	for(int i=1; i<=n; ++i) {
		if(s[i-1]=='0' || s[i-1]=='?') {
			pref[i] = pref[i-1] - 1;
		}
		else{
			pref[i] = pref[i-1] + 1;	
		}
		prefv[2*n + pref[i]].push_back(i);
	}
	int lo = 1, hi = n-1, mid, res=n;
	while(lo <= hi) {
		mid = (lo+hi)/2;
		if(solve(mid)) {
			hi = mid-1;
			res = mid;
		}
		else {
			lo = mid+1;
		}
	}
	//cerr<<solve(1)<<'\n';
	cout<<res;
}

