		a[i] = (s[i] == '1' ? +1 : -1);
		if (s[i] == '?') {
			neg.insert(i);
		}
		upd(i + 1, n, a[i]);
	}
	int answer = qmax(0, n).x - qmin(0, n).x;
	for (int iter = 0; clock() < 1.9 * CLOCKS_PER_SEC; ++iter) {
