int calc(string S) {
	int N = S.size();
	int ans = 0;
	REP(l, N) {
		FOR(r, l + 1, N+1) {
			int c0 = 0, c1 = 0;
			FOR(i, l, r) {
				if (S[i] == '0')c0++;
				else c1++;
			}
			chmax(ans, abs(c0 - c1));
		}
	}
	return ans;
}

