	void add(int t, int v)
	{
		mn[t] += v;
		mx[t] += v;
		dlt[t] += v;
	}
	void push(int t)
	{
		if(dlt[t])
		{
			add(ls, dlt[t]);
			add(rs, dlt[t]);
			dlt[t] = 0;
		}
	}
	void modify(int l, int r, int v, int tl, int tr, int t)
	{
		if(l <= tl && tr <= r)
		{
			add(t, v);
			return;
		}
		push(t);
		int mid = (tl + tr) / 2;
		if(l <= mid) modify(l, r, v, tl, mid, ls);
		if(r > mid) modify(l, r, v, mid+1, tr, rs);
		mn[t] = std::min(mn[ls], mn[rs]);
		mx[t] = std::max(mx[ls], mx[rs]);
	}
	int qmin(int l, int r, int tl, int tr, int t)
	{
		if(l <= tl && tr <= r) return mn[t];
		push(t);
		int mid = (tl + tr) / 2, ret = inf;
		if(l <= mid) ret = std::min(ret, qmin(l, r, tl, mid, ls));
		if(r > mid) ret = std::min(ret, qmin(l, r, mid+1, tr, rs));
		return ret;
	}
	int qmax(int l, int r, int tl, int tr, int t)
	{
		if(l <= tl && tr <= r) return mx[t];
		push(t);
		int mid = (tl + tr) / 2, ret = -inf;
		if(l <= mid) ret = std::max(ret, qmax(l, r, tl, mid, ls));
		if(r > mid) ret = std::max(ret, qmax(l, r, mid+1, tr, rs));
		return ret;
	}
	int qfirst(int v, int tl, int tr, int t)
	{
		if(mn[t] > v) return tr + 1;
		if(tl == tr) return tl;
		push(t);
		int mid = (tl + tr) / 2;
		if(mn[ls] == v) return qfirst(v, tl, mid, ls);
		else return qfirst(v, mid+1, tr, rs);
	}
