	cin.tie(0);
	cout.tie(0);
	cout << fixed << setprecision(10);
	string S;
	cin >> S;
	int N = S.length();
	int D_mi = 0, D_mx = N;
	while(D_mx-D_mi > 1) {
		int D = (D_mi+D_mx)/2;
		int L = -D, R = 0;
		bool ok = true;
		for(int i = 0; i < N; i++) {
			int L_n[2], R_n[2];
			if(S[i] == '1' || S[i] == '?') {
				// [L, L+D] ... [R, R+D] -> [L+1, L+1+D] ... [R+1, R+1+D]
				if(L < 0) {
					L_n[0] = L+1;
					R_n[0] = R+1;
					while(L_n[0] <= R_n[0] && R_n[0] > 0) R_n[0]--;
				}
				else L_n[0] = 1, R_n[0] = 0;
			}
			else L_n[0] = 1, R_n[0] = 0;
			if(S[i] == '0' || S[i] == '?') {
				// [L, L+D] ... [R, R+D] -> [L-1, L-1+D] ... [R-1, R-1+D]
				if(R+D > 0) {
					L_n[1] = L-1;
					R_n[1] = R-1;
					while(L_n[1] <= R_n[1] && L_n[1]+D < 0) L_n[1]++;
				}
				else L_n[1] = 1, R_n[1] = 0;
			}
			else L_n[1] = 1, R_n[1] = 0;
			if(L_n[0] > R_n[0] && L_n[1] > R_n[1]) {
				ok = false;
				break;
			}
			else if(L_n[0] > R_n[0]) {
				L = L_n[1];
				R = R_n[1];
			}
			else if(L_n[1] > R_n[1]) {
				L = L_n[0];
				R = R_n[0];
			}
			else {
				L = min(L_n[0], L_n[1]);
				R = max(R_n[0], R_n[1]);
			}
		}
		if(!ok) D_mi = D;
		else D_mx = D;
	}
	cout << D_mx << "\n";
}

