void build(int x,int l,int r){
	if(l==r){
		tr[x]=(seg){sa[l],sb[l],l};
		return;
	}
	int mid=(l+r)/2;
	build(x+x,l,mid);
	build(x+x+1,mid+1,r);
	pushup(x);
}
