  REP(i, n+1) t[TOUR+i].mn = t[TOUR+i].mx = pref[i];
  FOR(i, n+1, TOUR) {
    t[TOUR+i].mn = 1e9;
    t[TOUR+i].mx = -1e9;
  }

  for (int i=TOUR-1; i; i--)
    update(i);
}

int main()
{
  scanf(" %s", s);
  init();

  int sol = -t[1].mn + t[1].mx;

  for(;;) {
    int pos = get_first_min(1, 0, TOUR, t[1].mn + 1);
    auto its = S.lower_bound(pos);
    if (its == S.end() || *its > pos) {
      if (its != S.begin())
        its--;
    }

    if (its == S.end() || *its > pos) {
      pos = get_first_min(1, 0, TOUR, t[1].mn);
      its = S.lower_bound(pos);
      if (its == S.end() || *its > pos) {
        if (its == S.begin()) break;
