            if(memo[now-1]) {
                s[now-1] = (s[now] != '0' ? '0' : '1');
                memo[now-1] = 0;
                if(s[now-2] == '?') {
                    push(now-1, s[now-1] == 1, 1);
                }
            }
        } else {
            if(memo[now+1]) {
                s[now+1] = (s[now] != '0' ? '0' : '1');
                memo[now+1] = 0;
                if(s[now+2] == '?') {
                    push(now+1, s[now+1] == 1, 0);
                }
            }
        }
    }
    vector<int> zero_num(s_size, 0), one_num(s_size, 0);
    rep(i, s_size-1) {
        if(s[i] == '0') ++zero_num[i];
        else ++one_num[i];
        zero_num[i+1] = zero_num[i];
