        div[1] = max(div[1], one_num[i] - zero_num[i]);
        div2[0] = min(div2[0], zero_num[i] - one_num[i]);
        div2[1] = min(div[1], one_num[i] - zero_num[i]);
    }
    vector<int> div_fin(6, 0);
    div_fin[0] = div[0] + div2[1];
    div_fin[1] = div[1] + div2[0];
    div_fin[2] = abs(div[0]-div[1]);
    div_fin[3] = abs(div2[0]-div_fin[1]);
    div_fin[4] = div[0] + div2[0];
    div_fin[5] = div[1] + div2[1];

    int ans = 0;
    rep(i, 6) {
        ans = max(ans, div_fin[i]);
    }
    cout << ans << endl;
}

