struct solver
{

    solver()
    {
        string s; cin>>s;
        reverse(__all(s));
        const int n(s.size());

        auto ff=[&](const int k, bool turn)->bool
        {
            int low=0;
            int bnd=k/2,pbnd=(k-1)/2;
            if(!k) pbnd=-1;
            if(!turn) swap(bnd,pbnd);
            int up=bnd;
            for(char d: s)
            {
                if(d=='?')
                {
                    if(turn)
                    {
                        if(up<bnd) up++;
                    }
                    else
                    {
                        if(low>0) low--;
                    }
                }
                else if(d=='1')
                {
                    if(!turn)
                    {
                        if(low>0) low--;
                        up--;
                    }
                }
                else
                {
                    if(turn)
                    {
                        if(up<bnd) up++;
                        low++;
                    }
                }
                if(low>up) return false;
                turn^=1;
                swap(bnd,pbnd);
            }
            return true;
        };

        auto f=[&](const int k)->bool
        {
            return ff(k,false) or ff(k,true);
        };

        cout << binary(n,-1,f) << "\n";
    }
};
