int pre[1000005];
const int N=1e6+5;
int tr[4*N],lazy[4*N];
void add(int seg, int ll, int rr, int l, int r, int val) {
	if(ll>r||l>rr)
		return;
	if(l<=ll&&rr<=r) {
		tr[seg]+=val;
		lazy[seg]+=val;
		return;
	}
	if(lazy[seg]) {
		tr[seg<<1]+=lazy[seg];
		tr[seg<<1|1]+=lazy[seg];
		lazy[seg<<1]+=lazy[seg];
		lazy[seg<<1|1]+=lazy[seg];
		lazy[seg]=0;
	}
	add(seg<<1,ll,(ll+rr)/2,l,r,val);
	add(seg<<1|1,1+(ll+rr)/2,rr,l,r,val);
	tr[seg]=max(tr[seg<<1],tr[seg<<1|1]);
}
int query(int seg, int ll, int rr, int p) {
	if(ll==p&&rr==p) {
		return tr[seg];
	}
	if((ll+rr)/2>=p)
		return query(seg<<1,ll,(ll+rr)/2,p);
	else
		return query(seg<<1|1,1+(ll+rr)/2,rr,p);
}
void solve() {
	string s;
	cin>>s;
	int n=sz(s);
	s='0'+s;
	set<int> q;
	vi lami;
	lami.pb(0);
	fr(i,1,n) {
		if(s[i]=='?') {
			q.insert(i);
			s[i]='0';
		}
		pre[i]=pre[i-1]+2*s[i]-'0'-'1';
		if(pre[i]<pre[lami.back()])
			lami.pb(i);
	}
	fr(i,0,n)
		add(1,0,n,i,i,pre[i]);
	if(lami.empty()) {
		cout<<*max_element(pre,pre+n+1)<<endl;
		return;
	}
	set<int> q2=q;
	vi lami2=lami;
	int ans=(*max_element(pre,pre+n+1))-(*min_element(pre+1, pre+n+1));
	for(int i=-n-1; i<=0; i+=2) {
		while(query(1,0,n,lami[sz(lami)-2])<i)
			lami.pop_back();
		if(query(1,0,n,lami.back())<i) {
			auto it=q2.upper_bound(lami.back());
			if(it==q2.begin()) {
				break;
			} else {
				it--;
				add(1,0,n,*it,n,+2);
				q2.erase(it);
			}
		}
		ans=min(ans,abs(i-tr[1]));
	}
	swap(lami,lami2);
	swap(q2,q);
	memset(tr,0,sizeof(tr));
	memset(lazy,0,sizeof(lazy));
	fr(i,0,n)
		add(1,0,n,i,i,pre[i]);
	for(int i=-n; i<=0; i+=2) {
		while(query(1,0,n,lami[sz(lami)-2])<i)
			lami.pop_back();
		if(query(1,0,n,lami.back())<i) {
			auto it=q2.upper_bound(lami.back());
			if(it==q2.begin()) {
				break;
			} else {
				it--;
				add(1,0,n,*it,n,+2);
				q2.erase(it);
			}
		}
		ans=min(ans,abs(i-tr[1]));
	}
	cout<<ans<<endl;
}

