        if(i > 0 && s[i] != '?' && s[i-1] == '?') {
            push(i, s[i] == 1, 1);
        }
        if(i < s_size-1 && s[i] != '?' && s[i+1] == '?') {
            push(i, s[i] == 1, 0);
        }
    }

