int solve() {
	memset(p, 0, sizeof p);//prefix sum
	memset(sm, 0, sizeof sm);//suffix min of prefix sums
	int g_min = 0, g_max = 0;
	for(int i = 1; i <= n; i++) {
		p[i] = p[i-1] + (s[i] == '1' ? -1 : 1);
		assert(s[i] == '0' || s[i] == '1' || s[i] == '?');
		sm[i] = p[i];
	}
	for(int i = n; i--;) sm[i] = min(sm[i], sm[i+1]);
	g_min = sm[0];
	for(int run = 0, i = 0; i <= n; i++) {
		sm[i] += run;
		p[i] += run;
		if(s[i] == '?' && sm[i] - 2 >= g_min) {
			sm[i] -= 2;
			p[i] -= 2;
			run -= 2;
		}
		g_max = max(g_max, p[i]);
	}
	return g_max - g_min;
}
