struct SegTree {
	struct Node {
		int push;
		int maxval;

		Node() : push(0), maxval(0) {};

		Node Merge(const Node &rhs) const {
			Node ans;
			ans.maxval = max(maxval, rhs.maxval);
			return ans;
		}
	};

	vector<Node> nodes;
	int base;

	SegTree(int n) : base(1) {
		while (base < n + 1) { base *= 2; }
		nodes.resize(base * 2);
		for (int i = base-1; i >= 0; --i) {
			nodes[i] = nodes[i*2].Merge(nodes[i*2+1]);
		}
	}

	int lv, rv, valv;

	void Touch(int v) {
		if (v < base) {
			for (int s : {v*2, v*2+1}) {
				nodes[s].maxval += nodes[v].push;
				nodes[s].push += nodes[v].push;
			}
		}
		nodes[v].push = 0;
	}

	void AddValRec(int lbase, int rbase, int v) {
		if (lbase >= rv || rbase <= lv) { return; }
		Touch(v);
		if (lv <= lbase && rbase <= rv) {
			nodes[v].maxval += valv;
			nodes[v].push += valv;
			return;
		}

		const int mid = (lbase + rbase) / 2;
		AddValRec(lbase, mid, v*2);
		AddValRec(mid, rbase, v*2+1);
		nodes[v] = nodes[v*2].Merge(nodes[v*2+1]);
	}

	void AddVal(int L, int R, int val) {
		lv = L; rv = R; valv = val;
		return AddValRec(0, base, 1);
	}
};

