	int mx = 0, cur = 0;
	for (char ch : s) {
		cur += (ch == '1' ? 1 : -1);
		mx = max(mx, cur);
	}
	int ans = 1e9;

	for (int iter = 0; iter <= 1; ++iter) {
		SegTree tree(n + 2);
		for (int i = 0; i < n; ++i) {
			tree.AddVal(i + 1, n + 1, s[i] == '1' ? 1 : -1);
		}

		int cur = 0;
		int mnval = 0;

		for (int i = 0; i < n; ++i) {
			if (s[i] == '?') {
				tree.AddVal(i + 1, n + 1, +2);
				if (tree.nodes[1].maxval > mx) {
					tree.AddVal(i + 1, n + 1, -2);
					cur -= 1;
				} else {
					cur += 1;
				}
			} else {
				cur += (s[i] == '0' ? -1 : 1);
			}
			mnval = min(mnval, cur);
		}

		ans = min(ans, tree.nodes[1].maxval - mnval);
		++mx;
	}

	cout << ans << "\n";
}

