    int ok = n,ng = 0;
    while(ok-ng>1){
        int x = (ok+ng)>>1;
        int low = -x, high = x;
        bool flag = true;
        int now = 0, cnt = 0, mem = 0;
        for(auto e:s){
            if(e == '?'){
                now ++;
                cnt++;
                if(now > high){
                    cnt--;
                    now-=2;
                }
            }
            if(e == '0'){
                now--;
                if(now < low) flag = false;
            }
            if(e == '1'){
                now ++;
                if(now > high){
                    if(cnt == 0) flag = false;
                    else cnt--,now-=2;
                    if(mem) mem--,low++;
                }
            }
            if(now < low or now > high) flag = false;
            if(e == '?' and low > now - x) mem++;
            chmax(low,now-x);
            chmin(high,now+x);
            cnt = min(cnt,(now-low)/2);
            chmin(mem,cnt);
        }
        (flag ? ok : ng) = x;
    }
    cout << ok << endl;
}

