bool check(string s, int x) {

	int l = 0, r = x, step = 1;

	for (int i = 0; i < s.size(); ++i) {
		if (l == r) step = 1;

		if (s[i] == '0') {
			l--, r--;
			if (l < 0) {
				l += step;
			}
			if (l > r) {
				return false;
			}
		}
		else if (s[i] == '1') {
			l++, r++;
			if (r > x) {
				r -= step;
			}
			if (l > r) {
				return false;
			}
		}
		else {
			if (step == 2 || l != r) {
				l--, r++;
				if (l < 0) {
					l += step;
				}
				if (r > x) {
					r -= step;
				}
				if (l > r) {
					return false;
				}
			}
			else {
				l--, r++;
				step = 2;
				if (l < 0) {
					l += step;
				}
				if (r > x) {
					r -= step;
				}
				if (l > r) {
					return false;
				}
			}
		}
	}

	return true;

}

