int isPos(int u) {
  int l = 0, h = u;
  bool d = false;
  for (int i = 0; i < n; i++) {
    if (s[i] == '0')
      l--, h--;
    else if (s[i] == '1')
      l++, h++;
    else
      l--, h++;
    if (!d)
      l = max(l, 0), h = min(h, u);
    else {
      if (l < 0)
        l += 2;
      if (h > u)
        h -= 2;
    }
    if (l == h)
      d = true;
    if (l > h)
      return false;
  }
  return true;
}

