bool can(int k, string s) {
  for (int parity = 0; parity < 2; ++parity) {
    bool good = true;
    int lo = 0, hi = k;
    int par = parity;
    for (char c: s) {
      if (lo % 2 != par) ++lo;
      if (hi % 2 != par) --hi;
      par = !par;
      if (c == '1') ++lo, ++hi;
      else if (c == '0') --lo, --hi;
      else ++hi, --lo;
      lo = max(lo, 0);
      hi = min(hi, k);
      if (lo > k || hi < 0) {
        good = false;
      }
    }
    if (good) return true;
  }
  return false;
}

