		else
			cs[i] = max(0LL, cs[i + 1] - 1);
	}
	// co(cs);

	ll l = -1, r = n;
	ll ans = n;
	while(r - l > 1){
		ll m = (l + r) / 2;
		ll p = 0, min = 0;
