				if (p + 1 + cs[i + 1] <= m) ++p;
				else
					--p;
			}
			// co({s[i]});
			// co({m, i, p});
			if (p > m){
				flg = false;
				break;
			}
			chmin(min, p);
		}

		if(flg){
			chmin(ans, m - min);
			r = m;
		}else
			l = m;
	}
	// co(r);
	co(ans);

