			bit[i] += x;
			i += i&(-i);
		}
	}
};

string s;
BIT bit(1000005);

void update(llint p, llint x)
{
	llint v = bit.query(p), d = x - v;
	bit.add(p, d), bit.add(p+1, -d);
}

llint get(llint l, llint r)
{
	llint ub = r+1, lb = l-1, mid;
	while(ub-lb>1){
		mid = (ub+lb)/2;
		llint res = bit.query(mid);
		if(res > 0){
			if(res > inf/2){
				if(bit.query(mid+1) > 0 || bit.query(mid-1) > 0) lb = mid;
				else ub = mid;
			}
			else lb = mid;
		}
		else ub = mid;
	}
	return lb;
}

