			//cout << res << endl;
			if(res >= l) bit.add(l, -1), bit.add(res+1, 1);
			l--;
			update(l, inf);
		}
		if(s[i] == '1'){
			bit.add(l, 1), bit.add(r+1, -1);
			l++;
			llint x = min(bit.query(l-1), bit.query(l));
			update(l, x);
			update(l-1, inf);
		}
		if(s[i] == '?'){
			if(l == k){
				llint x = min(bit.query(k), bit.query(k+1))+1;
				llint res = get(l, r);
