bool tst(string s)
{
	int a=0;
	for(int i=0; i<s.length(); i++)
	{
		if(s[i]!='?')
		{
			if (s[i]% 2 == i % 2)a++;
		}
		else a++;
	}
	if(s.length()==a)return true;
	a=0;
	for(int i=0; i<s.length(); i++)
	{
		if(s[i]!='?')
		{
			if (s[i]% 2 != i % 2)a++;
		}
		else a++;
	}
	if(s.length()==a)return true;
	return false;
}
