int p[maxn], sm[maxn];
void solvep() {//stuff with +
	p[0] = 0;
	int gm = 0;
	for(int i = 1; i <= n; i++) {
		p[i] = p[i-1] + (s[i] == '-' ? -1 : 1);
		gm = min(gm, p[i]);
	}
	sm[n] = p[n];
	for(int i = n; i--;) sm[i] = min(p[i], sm[i+1]);


