	P id = { -INF,INF };

	auto calc = [&](ll mx) {
		SlidingWindowAggregation<P, decltype(f)> swag(f, id);
		REP(i, n)swag.push({ sum[i + 1],sum[i + 1] });
		ll mn = 0;
		ll d = 0;
		REP(i, n) {
			auto r = swag.fold_all();
			if (s[i] == '?' && r.first + d + 2 <= mx)d += 2;
			swag.pop();
			chmin(mn, sum[i + 1] + d);
		}
		return mx - mn;
	};
	ll ans = INF;
	chmin(ans, calc(mx));
	chmin(ans, calc(mx + 1));

	cout << ans << "\n";

	return 0;
}

