	vector<int> d;
	d.push_back(0);
	int now = 0;
	rep(i, s.size()) {
		now += (s[i] == '1' ? -1 : 1);
		d.push_back(now);
	}
	int mx = 0, mn = 0;
	for(int di: d) {
		chmax(mx, di);
		chmin(mn, di);
	}
	int mxind;
	rep(i, d.size()) {
		if (d[i] == mx) {
			mxind = i;
			break;
		}
	} // smallest index
	int mnind;
	rep(i, d.size()) {
		if (d[i] == mn) {
			mnind = i;
		}
