int n;
char s[maxn + 5];
int l0[maxn + 5], r0[maxn + 5], l1[maxn + 5], r1[maxn + 5];
std::set<int> S;

int pre(int p) {
	auto it = S.lower_bound(p);
	if (it == S.begin()) return 0;
	return *--it;
}

int nxt(int p) {
	auto it = S.upper_bound(p);
	if (it == S.end()) return 0;
	return *it;
}

int c[maxn + 5];

void Add(int p, int v) {
	for (int i = p; i <= maxn; i += i & -i)
		c[i] += v;
}

int query(int p) {
	int res = 0;
	for (int i = p; i; i ^= i & -i)
		res += c[i];
	return res;
}

int query(int l, int r) {
	if (l && l <= r) return query(r) - query(l - 1);
	else return 0;
}

signed main() {
#ifdef local
	freopen("in", "r", stdin);
	freopen("out", "w", stdout);
	freopen("log", "w", stderr);
#endif

	scanf("%s", s + 1);
	n = strlen(s + 1);


	for (int i = 1; i <= n; ++i)
		if (s[i] == '?') S.insert(i);
		else if (s[i] == '1') Add(i, 1);
		else Add(i, -1);

	int s0 = 0, s1 = 0;
	for (int i = 1; i <= n; ++i) {
		if (s[i] == '0') { ++s0; if (s1) --s1; }
		else if (s[i] == '1') { ++s1; if (s0) --s0; }
		else l0[i] = s0, l1[i] = s1, s0 = s1 = 0;
	}

	s0 = 0, s1 = 0;
	for (int i = n; i; --i) {
		if (s[i] == '0') { ++s0; if (s1) --s1; }
		else if (s[i] == '1') { ++s1; if (s0) --s0; }
		else r0[i] = s0, r1[i] = s1, s0 = s1 = 0;
	}

	#define Push(i) que.push(Pair(abs((l0[i] + r0[i]) - (l1[i] + r1[i])), i))
	std::priority_queue<Pair> que;
	for (int i = 1; i <= n; ++i)
		if (s[i] == '?' && (s[i - 1] != '?' || s[i + 1] != '?'))
			Push(i);

	while (!que.empty()) {
		int u = que.top().second; que.pop();
		if (s[u] != '?') continue;
		if (l0[u] + r0[u] > l1[u] + r1[u]) s[u] = '1', Add(u, 1);
		else s[u] = '0', Add(u, -1);
		int l = pre(u), r = nxt(u);
		chkmax(r0[l], -query(l, u) + r0[u]);
		chkmax(r1[l], query(l, u) + r1[u]), Push(l);
		chkmax(l0[r], -query(u, r) + l0[u]);
		chkmax(l1[r], query(u, r) + l1[u]), Push(r);
		S.erase(u);
	}

	int res = 0; s0 = s1 = 0;
	for (int i = 1; i <= n; ++i) {
		if (s[i] == '0') { chkmax(res, ++s0); if (s1) --s1; }
		else if (s[i] == '1') { chkmax(res, ++s1); if (s0) --s0; }
	}

	printf("%d\n", res);
	return 0;
}

