   int low = 1, high = N;
   while (low < high) {
      int mid = (low + high) >> 1;
      bool good = false;
      for (int z = 0; z < 2; ++z) {
         int l = z, r = mid;
         if ((r - l) & 1) --r;
         bool fail = false;
         for (int i = 0; i < N; ++i) {
