            } else if (S[i] == '0') {
               --l, --r;
            } else {
               --l, ++r;
            }
            if (l < 0) l += 2;
            if (r > mid) r -= 2;
            if (l > r) {
               fail = true;
               break;
            }
         }
         if (!fail) good = true;
      }
      if (good) high = mid;
      else low = mid + 1;
   }
   cout << low << "\n";
   return 0;
}

