	for(int i = n-1; i >= 0;i--) sm[i] = min(p[i], sm[i+1]);
	//for(int i = 0; i <= n; i++) cout << sm[i] << " ";

	int r = 0;
	for(int i = 0; i <= n; i++) {
		sm[i] += r;
		p[i] += r;
		if(s[i] == '?' && sm[i] - 2 >= gm) {
			r-=2;
			//cout <<"at " << i << '\n';
			sm[i] -= 2;
			p[i] -= 2;
			s[i] = '1';
		}
		tt[i] = r;
		if(s[i] == '?') s[i] = '0';
		//cout << p[i] << "\n";
	}
	//for(int i = 0; i <= n; i++) cout << tt[i] << " " << p[i] << '\n', p[i] += tt[i];
