void pull(node *n){
    n->Min=min(Min(n->l),Min(n->r));
    if(Max(n->l)>=Max(n->r)){
        n->pos=n->l->pos;
        n->Max=Max(n->l);
    }
    else{
        n->pos=n->r->pos;
        n->Max=Max(n->r);
    }
}
void push(node *n){
    n->l->add+=n->add;
    n->r->add+=n->add;
    n->add=0;
}
void build(node *n,int *a){
    if(n->a==n->b){
        n->Min=a[n->a];
        n->Max=a[n->a];
        n->pos=n->a;
     //   printf("?%d %d\n",n->a,a[n->a]);
        return ;
    }
    int mid=(n->a+n->b)/2;
    n->l=new node(n->a,mid);
    n->r=new node(mid+1,n->b);
    build(n->l,a);
    build(n->r,a);
    pull(n);
  //  printf("!%d %d %d %d\n",n->a,n->b,n->Min,n->Max);
}
void add(node *n,int l,int r,int k){
    if(n->a>=l&&n->b<=r){
        n->add+=k;
        return ;
    }
    if(n->b<l||n->a>r)return ;
    push(n);
    add(n->l,l,r,k);
    add(n->r,l,r,k);
    pull(n);
}
