void solve()
{
	string S;  cin >> S;
	ll n=sz(S);

	//1になれるかはんてい
	{
		ll eve=-1;
		ll odd=-1;
		bool isOK=true;
		rep(i, 0, n-1){
			if (S[i]=='?')continue;
			if (i%2==0){
				if (eve==-1){
					eve=S[i]-'0';
				}
				else if (eve!=S[i]-'0'){
					isOK=false;
					break;
				}
			}
			else{
				if (odd==-1){
					odd=S[i]-'0';
				}
				else if (odd!=S[i]-'0'){
					isOK=false;
					break;
				}
			}
		}
		if (eve==odd) isOK=false;
		if (isOK)bye(1);
	}
	string T;
	{
		ll st=0;
		rep(i, 0, n-1){
			if (S[i]!='?'){
				st=i;
				break;
			}
		}
		ll en=n-1;
		dep(i, n-1, 0){
			if (S[i]!='?'){
				en=i;
				break;
			}
		}
		T=S.substr(st, en-st+1);
	}
	ll m=sz(T);

	ll mn=0, mx=1;
	ll u, l;
	if (T[0]=='0'){
		u=l=0;
	}
	else{
		u=l=1;
	}
	bool uf=false;
	bool lf=false;

	rep(i, 0, m-1){
		if (S[i]=='1'){
			l++; u++;
			if (u==mx+1){
				if (u==l){
					mx=u;
				}
				else{
					uf=true;
				}
			}
			else if (u==mx+2){
				u-=2;
				uf=false;
			}

			if (l==mx){
				if (lf){
					mn--;
					l=u=mx;
					lf=uf=false;
				}
				else{
					l=u=mx;
					lf=uf=false;
				}
			}
		}
		else if (S[i]=='0'){
			l--; u--;
			if (l==mn-1){
				if (u==l){
					mn=l;
				}
				else{
					lf=true;
				}
			}
			else if (l==mn-2){
				l+=2;
				lf=false;
			}

			if (u==mn){
				if (uf){
					mx++;
					l=u=mn;
					lf=uf=false;
				}
				else{
					l=u=mn;
					lf=uf=false;
				}
			}
		}
		else{//?のとき
			ll preu=u, prel=l;
			bool preuf=uf, prelf=lf;
			u++; l--;
			if (u==mx+1)uf=true;
			if (l==mn-1)lf=true;

			if (u==mx+2){//上が2つはみ出す時
				u-=2;
				uf=false;
				if (prel==preu-2 && prelf==true) uf=true;
			}
			if (l==mn-2){
				l+=2;
				lf=false;
				if (preu==prel+2 && preuf==true) lf=true;
			}
		}
	}

	ll ans;
	if (lf==false or uf==false){
		ans=mx-mn;
	}
	else{
		if (u-l>=4){
			ans=mx-mn;
		}
		else{
			ans=mx-mn+1;
		}
	}
	cout << ans << '\n';
}

