int check (int n, int K) {
	int premin = 0, premax = 0, p = 0;
	int add = 0;
	for (int i = 1; i <= n; i ++) {
		npre[i] = p += s[i] == '1' ? 1 : -1;
		if (s[i] == '?' and sufmax[i] + add * 2 + 2 - premin <= K) {
			++ add;
			npre[i] = p += 2;
		}
		premin = std::min(premin, p);
	}
	int res = 0;
	sufmin[n] = npre[n];
	for (int i = n; i; i --)
		sufmin[i - 1] = std::min(sufmin[i], npre[i - 1]);
	for (int i = 1; i <= n; i ++) {
		res = std::min(res, sufmin[i] - premax);
		premax = std::max(premax, npre[i]);
	}
	return res;
}

