		pre[i] = pre[i - 1] + (s[i] == '1' ? 1 : -1);
	sufmax[n] = sufmin[n] = pre[n];
	for (int i = n; i; i --) {
		sufmax[i - 1] = std::max(sufmax[i], pre[i - 1]);
		sufmin[i - 1] = std::min(sufmin[i], pre[i - 1]);
	}

	int max = 0, premin = 0, p = 0;
	for (int i = 1; i <= n; i ++) {
		p += s[i] == '1' ? 1 : -1;
		max = std::max(max, sufmax[i] - premin);
		premin = std::min(premin, p);
	}

	int l = max, r = n;
	while (l < r) {
		int mid = (l + r) >> 1;
		if (check(n, mid) >= - mid)
			r = mid;
		else
			l = mid + 1;
	}

	printf("%d\n", l);
}

