		co(1);
		return 0;
	}

	ll t = -1;
	ll l = 0, r = n;
	while(r - l > 1){
		ll m = (l + r) / 2;
		ll mi = 0, ma = m;
		if(ma - mi > 0){
			repr(i, n){
				if (s[i] == '0'){
					++mi;
					if (ma < m) ++ma;
				}
				else if(s[i] == '1'){
					--ma;
					if (mi > 0) --mi;
				}else{
					if (mi > 0) --mi;
					else if(t > 0) ++mi;
					if (ma < m) ++ma;
					else if(t > 0) --ma;
				}

				if (mi > ma) break;
			}

			--t;

			if (ma == mi) t = mi + 10000000;

			if (mi <= ma) r = m;
			else
				l = m;
		}else{
			bitset<2005> bits(0), range(0);
			rep(i, ma - mi + 1) bits.set(i);
			rep(i, ma - mi + 1) range.set(i);
			repr(i, n){
				bitset<2005> nxt(0);
				if (s[i] == '0') nxt |= bits >> 1;
				else if(s[i] == '1')
					nxt |= bits << 1;
				else{
					nxt |= bits << 1;
					nxt |= bits >> 1;
				}
				nxt &= range;
				swap(nxt, bits);
