bool che(ll m,ll l,ll r){
    rep(i,0,n-1){
        if(s[i]=='0'){
            l--;r--;
            if(l<0)l+=2;
        }else if(s[i]=='1'){
            l++;r++;
            if(r>m)r-=2;
        }else{
            if(l>0)l--;
            else l++;
            if(r<m)r++;
            else r--;
        }
        if(l>r)return false;
    }
    return true;
}
bool check(ll m){
    if(che(m,0,m/2*2))return true;
    if(che(m,1,(m-1)/2*2+1))return true;
    return false;
}


