	for(int i = n-1; i >= 0;i--) sm[i] = min(p[i], sm[i+1]);
	//for(int i = 0; i <= n; i++) cout << sm[i] << " ";

	//for(int i = 0; i <= n; i++) cout << p[i] << ' '; cout << '\n';
