		sm[i] += r;
		p[i] += r;
		//cout << i << " " << sm[i] << " " << sm[i]-2 << " " << gm << '\n';
		if(s[i] == '?' && sm[i] - 2 >= gm) {
			r-=2;
			//cout <<"at " << i << '\n';
			sm[i] -= 2;
			p[i] -= 2;
			s[i] = '1';
		}
		tt[i] = r;
		if(s[i] == '?') s[i] = '0';
		//cout << p[i] << "\n";
	}
	//for(int i = 0; i <= n; i++) cout << p[i] << ' '; cout << '\n';
