const Int INF = 1e9;
Int ans=INF;

void solve(string s){
  Int n=s.size();

  using P = pair<Int, Int>;
  auto f=[&](P a,P b){return P(max(a.first,b.first),min(a.second,b.second));};
  auto g=[&](P a,Int b){return P(a.first+b,a.second+b);};
  auto h=[&](Int a,Int b){return a+b;};

  P ti(-INF,INF);
  Int ei(0);
  SegmentTree seg(f,g,h,ti,ei);

  vector<P> vp(n+1);

  Int sum=0;
  vector<Int> qs;
  for(Int i=0;i<n;i++){
    vp[i]=P(i-sum*2,i-sum*2);

    if(s[i]=='?')
      qs.emplace_back(i);

    if(s[i]=='1') sum++;
  }
  vp[n]=P(n-sum*2,n-sum*2);
  seg.build(vp);

  auto check=[&](){
    auto p=seg.query(0,n+1);
    chmin(ans,p.first-p.second);
  };
  check();

  // reverse(qs.begin(),qs.end());
  for(Int q:qs){
    Int mi=seg.query(0,q+1).second;
    auto p=seg.query(q+1,n+1);
    if(p.second-2>=mi)
      seg.update(q+1,n+1,-2);
    check();
  }
}

