            seg.upd(i, n - 1, +1);
        }
        else {
            seg.upd(i, n - 1, -1);
        }
    }
    auto calc = [&] () {
        return max(0, seg.st2[1].fi) - min(0, seg.st[1].fi);
    };
    int res = calc();
    set<int> st, st2;
    FOR(i, 0, n) if (s[i] == '?') {
        st.insert(i);
