template <typename T>
struct SegmentTree{
  using F = function<T(T,T)>;
  int n;
  F f;
  T ti;
  vector<T> dat;

  SegmentTree(){}
  SegmentTree(F f,T ti):f(f),ti(ti){}

  void init(int n_){
	n=1;
	while(n<n_) n<<=1;
	dat.assign(n<<1,ti);
  }

  void build(const vector<T> &v){
	int n_=v.size();
	init(n_);
	for(int i=0;i<n_;i++) dat[n+i]=v[i];
	for(int i=n-1;i;i--)
	  dat[i]=f(dat[(i<<1)|0],dat[(i<<1)|1]);
  }

  void set_val(int k,T x){
	dat[k+=n]=x;
	while(k>>=1)
	  dat[k]=f(dat[(k<<1)|0],dat[(k<<1)|1]);
  }

  T query(int a,int b){
	if(a>=b) return ti;
	T vl=ti,vr=ti;
	for(int l=a+n,r=b+n;l<r;l>>=1,r>>=1) {
	  if(l&1) vl=f(vl,dat[l++]);
	  if(r&1) vr=f(dat[--r],vr);
	}
	return f(vl,vr);
  }

  template<typename C>
  int find(int st,C &check,T &acc,int k,int l,int r){
	if(l+1==r){
	  acc=f(acc,dat[k]);
	  return check(acc)?k-n:-1;
	}
	int m=(l+r)>>1;
	if(m<=st) return find(st,check,acc,(k<<1)|1,m,r);
	if(st<=l&&!check(f(acc,dat[k]))){
	  acc=f(acc,dat[k]);
	  return -1;
	}
	int vl=find(st,check,acc,(k<<1)|0,l,m);
	if(~vl) return vl;
	return find(st,check,acc,(k<<1)|1,m,r);
  }

  template<typename C>
  int find(int st,C &check){
	T acc=ti;
	return find(st,check,acc,1,0,n);
  }
  //アウトの条件を渡す
};

void solve(){
	string s;
	cin >> s;
	int N = s.size(),ma = 0;
	//zero
		vector<int>zsum(N + 1);
		REP(i,N){
			if(s[i] == '0')zsum[i + 1] += zsum[i] + 1;
			else zsum[i + 1] += zsum[i] - 1;
		}
		SegmentTree<pair<int,int>>zseg([](pair<int,int>a,pair<int,int>b){return min(a,b);},{0,0});
		zseg.build(vector<pair<int,int>>(N + 1));
		REP(i,N + 1){
			zseg.set_val(i,{zsum[i],i});
		}
		FOR(i,1,N + 1){
			int it = zseg.query(0,i).first;
			CHMAX(ma,zsum[i] - it);
		}

	//one
		vector<int>osum(N + 1);
		REP(i,N){
			if(s[i] == '1')osum[i + 1] += osum[i] + 1;
			else osum[i + 1] += osum[i] - 1;
		}
		SegmentTree<pair<int,int>>oseg([](pair<int,int>a,pair<int,int>b){return min(a,b);},{0,0});
		oseg.build(vector<pair<int,int>>(N + 1));
		REP(i,N + 1){
			oseg.set_val(i,{osum[i],i});
		}
		FOR(i,1,N + 1){
			int it = oseg.query(0,i).first;
			CHMAX(ma,osum[i] - it);
		}
	vector<pair<pair<int,int>,int>>v;
	FOR(i,1,N + 1){
		auto[val,idx] = zseg.query(0,i);
		if(zsum[i] - val == ma){
			v.emplace_back(pair<int,int>(idx,i),0);
		}
	}
	FOR(i,1,N + 1){
		auto[val,idx] = oseg.query(0,i);
		if(osum[i] - val == ma){
			v.emplace_back(pair<int,int>(idx,i),1);
		}
	}
	sort(ALL(v));
	int flg = 0;
	REP(i,(int)v.size() - 1){
		//out(v[i].first.first,v[i].first.second,v[i + 1].first.first,v[i + 1].first.second,v[i].second,v[i + 1].second);
		if(v[i + 1].first.first <= v[i].first.second)continue;
		int cnt = 0;
		int z = 0;
		int o = 0;
		if(v[i].second == 0)z += ma;
		else o += ma;
		if(v[i + 1].second == 0)z += ma;
		else o += ma;
		FOR(j,v[i].first.second,v[i + 1].first.first){
			if(s[j] == '?')++cnt;
		}
		if(v[i].second == v[i + 1].second && cnt % 2 == 0)flg = 1;
		else if(v[i].second != v[i + 1].second && cnt % 2)flg = 1;
	}
	out(ma + flg);
}

signed main(){
	IOS();
	int Q = 1;
	//cin >> Q;
	while(Q--)solve();
}

