int calc(int z) {
    int det = 0,mn = 0,sum = 0;
    rep(i,1,n) {
        sum += a[i];
        if(s[i] == '?') {
            if (mx[i] + det + 2 <= z) {
                det += 2;
                sum += 2;
            }
        }
        cmin(mn,sum);
    }
    return z-mn;
}

