        ++sum;
      } else if (s[i] == '0') {
        --sum;
      } else if (capacity[i + 1] > count) {
        ++sum;
        ++count;
      } else {
        --sum;
      }
      tempMaxPrefix = max(tempMaxPrefix, sum);
      tempMinPrefix = min(tempMinPrefix, sum);
    }
    return tempMaxPrefix - tempMinPrefix;
  };
  cout << min(solve(maxPrefix), solve(maxPrefix + 1));
  return 0;
}

