int n;
char s[1234567];
int val[1234567];

void solve() {
	scanf("%s", s);
	n = strlen(s);
	val[0] = 0;
	FOR(i,0,n) {
		if (s[i] == '0' || s[i] == '?') {
			val[i+1] = val[i] - 1;
		} else {
			val[i+1] = val[i] + 1;
		}
	}
	int maxi = val[0], mini = val[0];
	FOR(i,1,n+1) {
		maxi = max(maxi, val[i]);
		mini = min(mini, val[i]);
	}
	int ans = maxi - mini;
	int last_maxi = 0;
	int first_mini = n;
	FOR(i,0,n+1) if (val[i] == maxi) last_maxi = i;
	FORD(i,n,0) if (val[i] == mini) first_mini = i;
	if (first_mini < last_maxi) {
		printf("%d\n", ans);
		return;
	}
	int max_after = mini;
	FOR(i,first_mini,n+1) {
		max_after = max(max_after, val[i]);
	}
	int do_gory = 0;
	FOR(i,last_maxi, first_mini) {
		if (s[i] == '?') do_gory++;
	}
	ans = ans - min(do_gory, maxi - max_after);
	printf("%d\n", ans);
}

int main() {
	int z = 1;
	while (z--) {
		solve();
	}
}

