    int minu = 0, maxu = 0;
    int ans = 1;
    for (int i = 0; i < n; ++i)
    {
        if (a[i] == '0')
        {
            --minu;
            --maxu;
        }
        else if (a[i] == '1')
        {
            ++minu;
            ++maxu;
        }
        else
        {
            ++minu;
            --maxu;
            minu = min(0, minu);
            maxu = max(0, maxu);
        }
        ans = max(ans, max(abs(minu), abs(maxu)));
    }
    ans = max(ans, 2);
    printf("%d\n", ans);
}

