    bool flag[2];
    flag[0] = 1;
    flag[1] = 1;

    for (int i = 0; i < 2; i++) {
        int low, high;
        if (i == 0) {
            low = 0;
            high = (d / 2) * 2;
        } else {
            low = 1;
            high = ((d - 1) / 2) * 2 + 1;
        }

        for (auto& c : S) {
            if (c == '?') {
                if (high == 0) {
                    low = 1;
                    high = 1;
                } else if (low == d) {
                    low = d - 1;
                    high = d - 1;
                } else {
                    if (low == 0) {
                        low = 1;
                    } else {
                        low--;
                    }
                    if (high == d)
                        high--;
                    else {
                        high++;
                    }
                }
            } else if (c == '0') {
                if (high == 0) {
                    flag[i] = false;
                    break;
                }
                high--;
                if (low == 0)
                    low = 1;
                else
                    low--;
            } else if (c == '1') {
                if (low == d) {
                    flag[i] = false;
                    break;
                }
                low++;

                if (high == d)
                    high--;

                else
                    high++;
            }
            if (low > high) {
                flag[i] = false;
                break;
            }
            // cerr << low << " " << high << endl;
        }
    }

    return flag[0] | flag[1];
}

