bool check(string& S, int limit)
{
	int i;
	int a = 0, b = limit, step = 1;
	FOR(i, 0, SIZE(S))
	{
		if(S[i] == '0')
		{
			--a;
			--b;
		}
		else if(S[i] == '1')
		{
			++a;
			++b;
		}
		else
		{
			--a;
			++b;
		}
		if(a < 0) a += step;
		if(b > limit) b -= step;
		if(a > b) return false;
		if(a == b) step = 2;
	}
	return true;
}

