tot seg[4123456];
int lazy[4123456];	
int pre[4123456],a[4123456];
int build(int node,int s,int e){
	lazy[node]=0;
	if(s==e){
		seg[node].minval=pre[s];
		seg[node].maxval=pre[s];
		seg[node].maxpos=s;
		return 0;
	}
	int mid=(s+e)/2;
	build(2*node,s,mid);
	build(2*node+1,mid+1,e);
	seg[node].minval=min(seg[2*node].minval,seg[2*node+1].minval);
	seg[node].maxval=max(seg[2*node].maxval,seg[2*node+1].maxval);
	if(seg[node].maxval == seg[2*node].maxval){
		seg[node].maxpos = seg[2*node].maxpos;
	}
	else{
		seg[node].maxpos = seg[2*node+1].maxpos;
	}
	return 0;
}

int update(int node,int s,int e,int l,int r){
	if(lazy[node]){
		seg[node].maxval+=lazy[node];
		seg[node].minval+=lazy[node];
		if(s!=e){
			lazy[2*node]+=lazy[node];
			lazy[2*node+1]+=lazy[node];
		}
		lazy[node]=0;
	}
	if(e<l || r<s){
		return 0;
	}
	if(l<=s && e<=r){
		lazy[node]=-2;
		seg[node].maxval+=lazy[node];
		seg[node].minval+=lazy[node];
		if(s!=e){
			lazy[2*node]+=lazy[node];
			lazy[2*node+1]+=lazy[node];
		}
		lazy[node]=0;
		return 0;
	}
	int mid = (s+e)/2;
	update(2*node,s,mid,l,r);
	update(2*node+1,mid+1,e,l,r);
	seg[node].minval=min(seg[2*node].minval,seg[2*node+1].minval);
	seg[node].maxval=max(seg[2*node].maxval,seg[2*node+1].maxval);
	if(seg[node].maxval == seg[2*node].maxval){
		seg[node].maxpos = seg[2*node].maxpos;
	}
	else{
		seg[node].maxpos = seg[2*node+1].maxpos;
	}
	return 0;
}

