int main(){
    string s; cin >> s;
    queue<P> st;
    int s_size = s.size();

    vector<bool> memo(s_size, 1);

    auto push = [&](int i, int num, bool which) {
        st.push(make_pair(make_pair(i, which), num));
    };

    rep(i, s_size) {
        if(i > 0 && s[i] != '?' && s[i-1] == '?') {
            push(i, s[i] == 1, 1);
        }
        if(i < s_size-1 && s[i] != '?' && s[i+1] == '?') {
            push(i, s[i] == 1, 0);
        }
    }

    while(!st.empty()) {
        P p = st.front(); st.pop();
        int now = p.first.first;

        if(p.first.second) {
            if(memo[now-1]) {
                s[now-1] = (s[now] != '0' ? '0' : '1');
                memo[now-1] = 0;
                if(s[now-2] == '?') {
                    push(now-1, s[now-1] == 1, 1);
                }
            }
        } else {
            if(memo[now+1]) {
                s[now+1] = (s[now] != '0' ? '0' : '1');
                memo[now+1] = 0;
                if(s[now+2] == '?') {
                    push(now+1, s[now+1] == 1, 0);
                }
            }
        }
    }
    vector<int> zero_num(s_size, 0), one_num(s_size, 0);
    rep(i, s_size-1) {
        if(s[i] == '0') ++zero_num[i];
        else ++one_num[i];
        zero_num[i+1] = zero_num[i];
        one_num[i+1] = one_num[i];
    }
    vector<int> div(2, 0);
    vector<int> div2(2, 1e9);
    vector<int> point(4);
    rep(i, s_size) {
        if(div[0] < zero_num[i] - one_num[i]) {
            point[0] = i;
            div[0] = zero_num[i] - one_num[i];
        }
        if(div[1] < one_num[i] - zero_num[i]) {
            point[1] = i;
            div[1] = one_num[i] - zero_num[i];
        }
        if(div2[0] > zero_num[i] - one_num[i]) {
            point[2] = i;
            div2[0] = zero_num[i] - one_num[i];
        }
        if(div2[1] > one_num[i] - zero_num[i]) {
            point[3] = i;
            div2[1] = one_num[i] - zero_num[i];
        }
    }

    vector<int> div_fin(6, 0);
    div_fin[0] = abs(abs(div[0]) + div2[1]);
    div_fin[1] = abs(abs(div[1]) + div2[0]);
    div_fin[2] = abs(abs(div[0]) + abs(div[1]))-1;
    div_fin[3] = abs(abs(div2[0]) + div2[1]);
    div_fin[4] = abs(abs(div[0]) + abs(div2[0]))-1;
    div_fin[5] = abs(abs(div[1]) + abs(div2[1]))-1;

    int ans = 0;
    rep(i, 6) {
        ans = max(ans, div_fin[i]);
    }
    cout << ans << endl;
}

