struct T {
	int sum, pre;
	T(): sum(0), pre(0) {}
	T(int sum, int pre): sum(sum), pre(pre) {}
	inline T operator + (const T &rhs) const {
		return T(sum + rhs.sum, min(pre, sum + rhs.pre));
	}
} t[maxn << 1];

void clr() {
	rep(i, maxn << 1) t[i] = T();
}

inline void upd(int x, int v) {
	t[x += maxn] = T(v, min(v, 0));
	while (x >>= 1) t[x] = t[x << 1] + t[x << 1 | 1];
}

