int fdiv2(int x) {
	return (x > 0 ? x / 2 : -((-x + 1) / 2));
}

bool check(string& s, int n, int d1, int d2) {
	vector<vector<int>> mx(2, vector<int>(n, n));
	int cnt = 0, delta = 0;
	bool ok = true;
	for (int i = 0; i < n; ++i) {
		if (s[i] == '?') {
			++cnt;
		} else {
			delta += (s[i] == '0' ? 1 : -1);
		}
		mx[0][i] = fdiv2(cnt - delta + d1);
		mx[1][i] = fdiv2(cnt + delta + d2);
	}
	for (int i = n - 2; i >= 0; --i) {
		mx[0][i] = min(mx[0][i], mx[0][i + 1]);
		mx[1][i] = min(mx[1][i], mx[1][i + 1]);
	}
	ok &= (mx[0][0] >= 0 and mx[1][0] >= 0);
	int c0 = 0, c1 = 0;
	for (int i = 0; i < n; ++i) {
		if (s[i] != '?') {
			continue;
		} else if (c0 >= mx[0][i] and c1 >= mx[1][i]) {
			ok = false;
			break;
		} else if (c0 < mx[0][i]) {
			++c0;
		} else {
			++c1;
		}
	}
	return ok;
}

