bool check_interval(ll l, ll r){
	ll st = 0, en = 0;
	forn(i,n){
		// if(l==0 && r==0) cout << i << ln;
		if(s[i]=='?'){
			en+=2;
		}
		ll curl = l+a[i], curr = r+a[i];
		if(curl%2) curl++;
		if(curr%2) curr--;
		// if(l==0 && r==0) cout << curl << " " << curr << ln;
		if(en<curl) return -1;
		else if(curr<st) return 1;
		st = max(st,curl);
		en = min(en,curr);
	}
	return 0;
}

bool check(ll len){
	ll l = 0,r=len;
	while(l!=r){
		ll high = (l+r)/2;
		ll v = check_interval(high-len,high);
		if(v==0) return 1;
		else if(v==-1){
			r = high-1;
		}
		else{
			l = high+1; 
		}
	}
	ll v = check_interval(l-len,l);
	// if(len==0) cout <<  v << ln;
	if(v==0) return 1;
	return 0;
}

void solve(){
	cin >> s;
	n = sz(s);
	ll v[n],sum[n];
	forn(i,n){
		if(s[i]=='1') {
			v[i]=(i ? v[i-1] : 0) + 1;
			sum[i] = (i ? sum[i-1] : 0);
		}
		else if(s[i]=='0') {
			v[i]=(i ? v[i-1] : 0) - 1;
			sum[i] = (i ? sum[i-1] : 0);
		}
		else {
			v[i]=(i ? v[i-1] : 0);
			sum[i] = (i ? sum[i-1] : 0) + 1;
		}
	}
	a.resize(n);
	forn(i,n) a[i] = sum[i]-v[i];
	ll l = 1,r=n;
	while(l!=r){
		ll len = (l+r)/2;
		// cout << len << " " << check(len) << ln;
		if(check(len)) r = len;
		else l = len+1;
	}
	cout << l << ln;
}

