    int n = s.size();
    int x_0 = 0;
    int x_1 = 0;
    if (posi < n)
    {
        n = posi;
    }
    for (int i = l; i <= n; i++)
    {
        if (s.at(i - 1) == '?')
        {
            if (x_0 <= x_1)
            {
                x_0++;
            }
            else
            {
                x_1++;
            }
        }
        else if (s.at(i - 1) == '0')
