		a[i+1]=2*cum[i+1]-(i+1);
	}
	for (int i=0;i<=2*n+2;i++)
	f[i]=1e9;
	for (int i=0;i<=n;i++)
	f[a[i]+n+2]=min(f[a[i]+n+2],i);
	printf("%d",min(solve(-n,n),solve(-n+1,n)));
}

