pair < int, int > uni (pair < int, int > a, pair < int, int > b)
{
    return {max (a.first, b.first), min (a.second, b.second)};
}

bool ok (int D)
{
    for (int par = 0; par < 2; par ++)
    {
        ///L = 2 * K + par for some K
        ///I'll have for all i, where s[i] = number of 1 in the prefix of i
        ///L <= i - 2 * s[i] <= L + D
        ///2K + par <= i - 2 * s[i] <=> 2 * s[i] <= i - 2K - par <=> s[i] <= (i - par) / 2 - K
        ///i - 2 * s[i] <= 2 * K + par + D <=> 2 * s[i] >= i - 2 * K - par - D <=> s[i] >= (i - par - D) / 2 - K
        int fixedS = 0, nr = 0;
        segm[0] = {-4 * N, 4 * N};
        for (int i=0; i<=N; i++)
        {
            int l, r = ((i == 0 && par == 1) ? -1 : (i - par) / 2);
            if ((i - par - D) % 2 == 0)
                l = (i - par - D) / 2;
            else
                l = (i - par - D + 1) / 2;
//            printf ("[%d, %d]\n", l, r);
            if (sir[i] == '?')
            {
                nr ++;
                segm[nr] = {l - fixedS, r - fixedS};
            }
            else
            {
                if (i > 0 && sir[i] == '1')
                    fixedS ++;
                segm[nr] = uni (segm[nr], {l - fixedS, r - fixedS});
            }
        }
        ///considering s2[i] = the number of 1s in the first i question marks,
        ///we have s2[i] is in segm[i] - K
        for (int i=1; i<=nr; i++)
            segm[i].first = max (segm[i].first, segm[i - 1].first),
            segm[i].second = min (segm[i].second, segm[i - 1].second + 1);
        bool isOk = 1;
        for (int i=0; i<=nr; i++)
            if (segm[i].first > segm[i].second)
                isOk = 0;
        if (isOk)
            return 1;
    }
    return 0;
}

