struct node{
    int maxv, minv, addv;
}t[maxn << 2];
#define ls (v << 1)
#define rs ((ls) | 1)
#define tm ((tl + tr) >> 1)
void update(int v){
    t[v].maxv = max(t[ls].maxv, t[rs].maxv);
    t[v].minv = min(t[ls].minv, t[rs].minv);
}
void add(int v, int x){
    t[v].maxv += x;
    t[v].minv += x;
    t[v].addv += x;
}
void push_down(int v){
    add(ls, t[v].addv);
    add(rs, t[v].addv);
    t[v].addv = 0;
}
void build(int v, int tl, int tr){
    if(tl == tr) t[v].maxv = t[v].minv = f[tm];
    else{
        build(ls, tl, tm);
        build(rs, tm + 1, tr);
        update(v);
    }
}
void update(int v, int tl, int tr, int L, int R){
    if(tl >= L and tr <= R) add(v, 2);
    else{
        push_down(v);
        if(L <= tm) update(ls, tl, tm, L, R);
        if(R > tm) update(rs, tm + 1, tr, L, R);
        update(v);
    }
}
int query(int v, int tl, int tr, int L, int R){
    if(tl >= L and tr <= R) return t[v].maxv;
    push_down(v);
    if(L > tm) return query(rs, tm + 1, tr, L, R);
    if(R <= tm) return query(ls, tl, tm, L, R);
    return max(query(ls, tl, tm, L, R), query(rs, tm + 1, tr, L, R));
}
