struct YZR{
	int a[N],his[N],n,pos,ans;

	int val[N<<2],lzy[N<<2];//max

	void pushdown(int k){
		lzy[k<<1]+=lzy[k];val[k<<1]+=lzy[k];
		lzy[k<<1|1]+=lzy[k];val[k<<1|1]+=lzy[k];
		lzy[k]=0;
	}
	void upd(int k){
		val[k]=max(val[k<<1],val[k<<1|1]);
	}
	void build(int k, int l, int r){
		if(l==r){val[k]=a[l];return;}
		int mid=(l+r)/2;
		build(k<<1,l,mid);build(k<<1|1,mid+1,r);
		upd(k);
	}
	void ini(int s, int mx, int *c){
		while(s<=mx)a[++n]=b[s],his[n]=c[s],s+=2;
		pos=1;while(pos<=n&&his[pos]==1e9)pos++;
		ans=pos<=n?a[pos]:1e9;
		build(1,1,n);
	//	cerr<<n<<" qwq "<<pos<<endl;
	//	rep(i,1,n)cerr<<a[i]<<' '<<his[i]<<' ';cerr<<endl;
	}
	void mdy(int k, int l, int r, int x, int L, int R){
		if(l==L&&r==R){lzy[k]+=x;val[k]+=x;return;}
		int mid=(L+R)/2;pushdown(k);
		if(r<=mid)mdy(k<<1,l,r,x,L,mid);
		else if(l>mid)mdy(k<<1|1,l,r,x,mid+1,R);
		else mdy(k<<1,l,mid,x,L,mid),mdy(k<<1|1,mid+1,r,x,mid+1,R);
		upd(k);
	}
	int find(int k, int lim, int l, int r){
		if(val[k]<lim)return n+1;
		if(l==r)return l;
		int mid=(l+r)/2;pushdown(k);
		if(val[k<<1]>=lim)return find(k<<1,lim,l,mid);
		return find(k<<1|1,lim,mid+1,r);
	}
	int qry(int k, int p, int l, int r){
		if(l==r)return val[k];
		int mid=(l+r)/2;pushdown(k);
		if(p<=mid)return qry(k<<1,p,l,mid);
		return qry(k<<1|1,p,mid+1,r);
	}
	void solve(int lim){//>=lim --; else ++
		int p=find(1,lim,1,n);
		if(p<=n)mdy(1,p,n,-1,1,n);
		if(1<=p-1)mdy(1,1,p-1,1,1,n);
	}
	void yzr(){if(pos<=n)umax(ans,qry(1,pos,1,n));}
	int qry(){
		return ans;
	}
}ji,ou;
