bool chk(int lim) {
	int top = 0;
	int nw_diff = 0; // 0 - 1
	clr();
	rep(i, n) {
		char c = s[i] == '?' ? '0' : s[i];
		if (s[i] == '?') stk[top ++] = i;
		int x = c == '0' ? 1 : -1;
		upd(i, x);
		ans[i] = x;
		nw_diff += x;
		if (nw_diff - t[1].pre > lim) {
			if (not top) return 0;
			-- top;
			ans[stk[top]] = -1;
			upd(stk[top], -1);
			nw_diff -= 2;
		}
	}
	{
		int nw_diff = 0, mn_diff = 0;
		rep(i, n) {
