struct Max_Seg_Tree {

	pi t[4*N];
	int lazy[4*N];

	void bld(int v = 1, int tl =0 , int tr = n) { 
		if(tl == tr - 1) {
			t[v] = {p[tl], tl};
		} else {
			int tm = (tl + tr) / 2;
			bld(v*2, tl, tm);
			bld(v*2+1, tm, tr);
			t[v] = max(t[v*2], t[v*2+1]);
		}
	}

	void push(int v) {
		if(lazy[v]) {
			lazy[v*2] += lazy[v];
			lazy[v*2+1] += lazy[v];
			t[v*2].F += lazy[v];
			t[v*2+1].F += lazy[v];
			lazy[v] = 0;
		}
	}

	void upd(int l, int r, int add, int v = 1, int tl = 0, int tr = n) {
		if(l >= r) return;
		if(l == tl && r == tr) {
			t[v].F += add;
			lazy[v] += add;
			return;
		}
		push(v);
		int tm = (tl + tr) / 2;
		upd(l, min(r, tm), add, v*2, tl, tm);
		upd(max(l, tm), r, add, v*2+1, tm, tr);
		t[v] = max(t[v*2], t[v*2+1]);
	}

	pi qry(int l, int r, int v = 1, int tl = 0, int tr = n) {
		if(l >= r) return {-INF, -INF};
		if(l == tl && r == tr) return t[v];
		push(v);
		int tm = (tl + tr) / 2;
		return max(qry(l, min(r, tm), v*2, tl, tm),
			qry(max(l, tm), r, v*2+1, tm, tr));
	}
} mxt;
struct Min_Seg_Tree {

	pi t[4*N];
	int lazy[4*N];

	void bld(int v = 1, int tl =0 , int tr = n) { 
		if(tl == tr - 1) {
