			lazy[v*2] += lazy[v];
			lazy[v*2+1] += lazy[v];
			t[v*2].F += lazy[v];
			t[v*2+1].F += lazy[v];
			lazy[v] = 0;
		}
	}

	void upd(int l, int r, int add, int v = 1, int tl = 0, int tr = n) {
		if(l >= r) return;
		if(l == tl && r == tr) {
			t[v].F += add;
			lazy[v] += add;
			return;
		}
		push(v);
		int tm = (tl + tr) / 2;
		upd(l, min(r, tm), add, v*2, tl, tm);
		upd(max(l, tm), r, add, v*2+1, tm, tr);
