              string tmp2 = to_stirng(tmp);
              S[i] = tmp2[0]; // string -> char
            }
          }
        }else{ // odd ?s
          if(ltr = '1'){
            for(lint i=0; i<cnt; i++){
              lint tmp = i % 2; // 0 1 0 1 ...
              string tmp2 = to_stirng(tmp);
              S[i] = tmp2[0]; // string -> char
            }
          }else{ // 0
            for(lint i=0; i<cnt; i++){
              lint tmp = i % 2; // 1 0 1 0 ...
              string tmp2 = to_stirng(tmp);
              S[i] = tmp2[0]; // string -> char
            }
          }
        }
      }else{ // リセット後ではない
        if(cnt % 2 == 0){ // even ?s
          if(deka == score[k]){
            for(lint i=0; i<cnt; i++){
              lint tmp = i % 2; // 0 1 0 1 ...
              string tmp2 = to_stirng(tmp);
              S[k + i] = tmp2[0]; // string -> char
            }
          }else{ // tibiと等しい場合は1 0 1 0 ... それ以外はどっちでもよい
            for(lint i=0; i<cnt; i++){
              lint tmp = i % 2; // 1 0 1 0 ...
              string tmp2 = to_stirng(tmp);
              S[k + i] = tmp2[0]; // string -> char
            }
          }
        }else{ // odd ?s 最後1個の?以外は上と同じ
          if(deka == score[k]){
            for(lint i=0; i<cnt-1; i++){
              lint tmp = i % 2; // 0 1 0 1 ...
              string tmp2 = to_stirng(tmp);
              S[k + i] = tmp2[0]; // string -> char
            }
          }else{ // tibiと等しい場合は1 0 1 0 ... それ以外はどっちでもよい
            for(lint i=0; i<cnt-1; i++){
              lint tmp = i % 2; // 1 0 1 0 ...
              string tmp2 = to_stirng(tmp);
              S[k + i] = tmp2[0]; // string -> char
            }
          } 
        } // ?はあと1個
      }
    }
    if(S[k]=='1'){
      score[k+1] = score[k] + 1;
      deka = max(score[k+1], deka);
    }
    if(S[k]=='0'){
      score[k+1] = score[k] - 1;
      tibi = min(score[k-1], tibi);
    }
  } // かたまりごとのdek,tib,las計算おわり

  dek.PB(deka);
  tib.PB(tibi);
  las.PB(score[L]);

  lint N = dek.size();
  lint mdeka = dek[0];
  lint mtibi = tib[0];
  lint mlast = las[0];

  if(N==1){
    cout << mdeka - mtibi << endl;
