int solve (int mx) {
	memset(st, 0, sizeof(st));
	memset(lz, 0, sizeof(lz));

	int acu = 0, mn = 0;

	forn (i, n) {
		char c = s[i];

		if (c == '1') acu++;
		else acu--;
		update(1, n, 1, i + 1, i + 1, acu);
	}

	acu = 0;
	forn (i, n) {
		char c = s[i];

		if (c == '1') acu++;
