int check(int v){
	int zeroes = 0, ones = 0, mx = 0;
	for(int i = 1; i <= n; ++i){
		char c = in[i];
		if(c == '0'){
			++zeroes;
		}
		else if(c == '1'){
			++ones;
			mx = max(mx, ones - zeroes);
		}
		else{
			if(zeroes - ones + limit[i] + 1 <= v)
				++zeroes;
			else{
				++ones;
				mx = max(mx, ones - zeroes);
			}
		}
	}

	return mx + v;
}

