int ok(int C) {
  array<array<int,2>,2> dp;
  for (int it = 0; it < 2; it++) {
    for (int i = 0; i < 2; i++)
      for (int j = 0; j < 2; j++)
        dp[i][j] = 0;
    dp[0][0] = 1 + it;
    dp[0][1] = C;
    if (dp[0][1] % 2 != (it ^ 1))
      dp[0][1]--;
    int ok = dp[0][0] <= dp[0][1];
    for (int i = 0; i < n && ok; i++) {
      dp[1][0] = dp[1][1] = 0;
      if (s[i] == '0') {
        dp[1][0] = dp[0][0] + 1;
        dp[1][1] = dp[0][1] + 1;
      } else if (s[i] == '1') {
        dp[1][0] = dp[0][0] - 1;
        dp[1][1] = dp[0][1] - 1;
      } else {
        dp[1][0] = dp[0][0] - 1;
        dp[1][1] = dp[0][1] + 1;
      }
      swap(dp[0], dp[1]);
      if (dp[0][0] < 1)
        dp[0][0] += 2;
      if (dp[0][1] > C)
        dp[0][1] -= 2;
      ok &= dp[0][0] <= dp[0][1];
      ok &= dp[0][0] <= C && dp[0][1] > 0;
    }
    if (ok)
      return 1;
  }
  return 0;
}

