string s;
ll n, ans = INF;
ll dp[1100000];
ll solve(ll ind){

    ll ma = 0, mi = 0, now = 0;
    REP(i, n){
        if (s[i] == '0') now--;
        if (s[i] == '1') now++;
        if (s[i] == '?'){
            if(now - 1 - dp[i] >= ind){
                now--;
            }
            else{
                now++;
            }
        }
        ma = max(now, ma);
        mi = min(now, mi);
    }
    //cout << ind << " " << abs(ma - mi) << endl;
    ans = min(ans, abs(ma - mi));
    return abs(ma - mi);
}
P sabu1(int from, int to) {
	for (;to - from > 200;) {
		int mid = (from + to) / 2;
		(solve(mid * 2) - solve((mid - 1) * 2) <= 0 ? from : to) = mid;
	}
	return P(from, to);
}
P sabu2(int from, int to) {
	for (;to - from > 200;) {
		int mid = (from + to) / 2;
		(solve(mid * 2 - 1) - solve((mid - 1) * 2 - 1) <= 0 ? from : to) = mid;
	}
	return P(from, to);
}
