                    sl--; sr--;
                    if(~(i+p)&1){
                        sl=max(sl, 1);
                    }
                }else if(s[i]=='1'){
                    l++; r++;
                    sl++; sr++;
                    if(~(i+q)&1){
                        sr=min(sr, -1);
                    }
                }else{
                    l--; r++;
                    sl--; sr++;
                    if(~(i+p)&1){
                        sl=max(sl, 1);
                    }
                    if(~(i+q)&1){
                        sr=min(sr, -1);
                    }
                }
                d=max(d, sl-sr);
                L=min(L, r-sl);
                R=max(R, l-sr);
            }
            ans=min(ans, max(d, R-L));
        }
    }
    cout<<ans<<endl;
    return 0;
}

