const int maxn = 1e6 + 10;
char s[maxn];
int n, mid, Min[maxn << 2], Max[maxn << 2], Add[maxn << 2], sum[maxn];
void pushup(int rt)
{
	Min[rt] = min(Min[ls], Min[rs]);
	Max[rt] = max(Max[ls], Max[rs]);
}
void lazy(int rt, int x)
{
	Min[rt] += x;
	Max[rt] += x;
	Add[rt] += x;
}
void pushdown(int rt)
{
	if(Add[rt])
	{
		lazy(ls, Add[rt]);
		lazy(rs, Add[rt]);
		Add[rt] = 0;
	}
}
void build(int rt, int l, int r)
{
	Add[rt] = 0;
	if(l == r)
	{
		Min[rt] = Max[rt] = 2 * sum[l] - l;
		return;
	}
	int mid = l + r >> 1;
	build(ls, l, mid); build(rs, mid + 1, r);
	pushup(rt);
} 
void update(int rt, int l, int r, int a, int b)
{
	if(a <= l && r <= b)
	{
		lazy(rt, 2);
		return;
	}
	pushdown(rt);
	int mid = l + r >> 1;
	if(a <= mid) update(ls, l, mid, a, b);
	if(b > mid) update(rs, mid + 1, r, a, b);
	pushup(rt);
}
int queryMin(int rt, int l, int r, int a, int b)
{
	if(a <= l && r <= b) return Min[rt];
	pushdown(rt);
	int mid = l + r >> 1;
	if(b <= mid) return queryMin(ls, l, mid, a, b);
	else if(a > mid) return queryMin(rs, mid + 1, r, a, b);
	else return min(queryMin(ls, l, mid, a, b), queryMin(rs, mid + 1, r, a, b));
}
int queryMax(int rt, int l, int r, int a, int b)
{
	if(a <= l && r <= b) return Max[rt];
	pushdown(rt);
	int mid = l + r >> 1;
	if(b <= mid) return queryMax(ls, l, mid, a, b);
	else if(a > mid) return queryMax(rs, mid + 1, r, a, b);
	else return max(queryMax(ls, l, mid, a, b), queryMax(rs, mid + 1, r, a, b));
}
bool check()
{
	build(1, 0, n);
	stack<int> sta;
	for(int i = 1; i <= n; ++i)
	{
		if(s[i] == '?') sta.push(i);
		if(queryMax(1, 0, n, 0, i - 1) - mid > queryMax(1, 0, n, i, i))
		{
