    int a[2] = {0, 0};

    int sol = 0;

    for (int i = 0; i < 2; ++i)
    {
        int res = 0, best = 0;
        int p = 0;

        for (auto x : s)
        {
            p++;
            int u = x == '?' ? i : x - '0';
            u = 2 * u - 1;
            if (i == 1)
                u *= -1;
            res = max(res + u, 0);

            // cout << "B: " << p << " " << x << " " << u << " " << res << " " << best << endl;

            if (x != '?' && (x - '0') != i)
            {
                // cout << "check" << endl;
