            }

            // cout << "A: " << p << " " << x << " " << u << " " << res << " " << best << endl;

            if (x != '?')
            {
                a[p & 1] |= 1 << (x - '0');
            }
        }

        // cout << "best: " << best << endl;
        sol = max(sol, best);
    }

    if (a[0] > a[1])
        swap(a[0], a[1]);

    // cout << a[0] << " " << a[1] << endl;
    if (a[1] == 0 || (a[0] < a[1] && a[1] < 3))
    {
