struct dat{
    ll h,l,a;
    dat(ll h,ll l,ll a):h(h),l(l),a(a){}
};
using v_dat=vector<dat>;

bool isok(v_dat &V, ll thresh,ll& highest, ll& lowest){
    v_ll X; ll s=0;
    for(ll i=0;i<V.size()-1;i++){
        s+=V[i].a;
        s++;
        X.pb((s+V[i+1].h-thresh+1)/2);
    }
    highest=0;lowest=0;
    ll a=V[0].a;
    if (V[0].h>thresh) return false;
    chmin(lowest,V[0].l);
    chmax(highest,V[0].h);
    ll down=0;
    for(ll i=1;i<V.size();i++){
        if (a+1+V[i].h<=thresh){
            if (down>=X[i-1]){
                chmin(lowest,a+1+V[i].l);
                chmax(highest,a+1+V[i].h);
                a=a+1+V[i].a;
            }else{
                down++;
            chmin(lowest,a-1+V[i].l);
            chmax(highest,a-1+V[i].h);
            a=a-1+V[i].a;
            }
        }else if (a-1+V[i].h<=thresh){
            down++;
            chmin(lowest,a-1+V[i].l);
            chmax(highest,a-1+V[i].h);
            a=a-1+V[i].a;
        }else return false;
    }
    return true;
}

int main(){
    string S;
    cin >> S;
    ll cur=0;
    v_dat V;
    while (cur<S.size()){
        dat d(0,0,0);
        while (cur<S.size()&&S[cur]!='?'){
            if (S[cur]=='0'){
                d.a--;
                chmin(d.l,d.a);
            }else{
                d.a++;
                chmax(d.h,d.a);
            }
            cur++;
        }
        cur++;
        V.pb(d);
    }

    ll ok=1000000LL;
    ll ng=-1;
    ll ans=10000000LL;

    while(ok-ng>1){
        ll mid=(ok+ng)/2;
        ll h,l;
        (isok(V,mid,h,l)?ok:ng)=mid;
        chmin(ans,h-l);
    }
    cout << ans << "\n";
}

