ll m, n, k, q;
int tree_min[T * 2];
int lazy_min[T * 2];

void push_min(int u){
	tree_min[u] += lazy_min[u];
	if(u < T){
		lazy_min[u * 2] += lazy_min[u];
		lazy_min[u * 2 + 1] += lazy_min[u];
	}
	lazy_min[u] = 0;
}

int ask_min(int pocz, int kon, int u = 1, int lo = 0, int hi = T - 1){
	push_min(u);
	if(kon < lo or hi < pocz)
		return INF;
	if(lo >= pocz and hi <= kon)
		return tree_min[u];
	int mid = (lo + hi) / 2;
	return min(ask_min(pocz, kon, u * 2, lo, mid), ask_min(pocz, kon, u * 2 + 1, mid + 1, hi));
}

void add_min(int pocz, int kon, int val, int u = 1, int lo = 0, int hi = T - 1){
	push_min(u);
	if(kon < lo or hi < pocz)
		return;
	if(lo >= pocz and hi <= kon){
		lazy_min[u] += val;
		push_min(u);
		return;
	}
	int mid = (lo + hi) / 2;
	add_min(pocz, kon, val, u * 2, lo, mid);
	add_min(pocz, kon, val, u * 2 + 1, mid + 1, hi);
	tree_min[u] = min(tree_min[u * 2], tree_min[u * 2 + 1]);
}		


int tree_max[T * 2];
int lazy_max[T * 2];

void push_max(int u){
	tree_max[u] += lazy_max[u];
	if(u < T){
		lazy_max[u * 2] += lazy_max[u];
		lazy_max[u * 2 + 1] += lazy_max[u];
	}
	lazy_max[u] = 0;
}

int ask_max(int pocz, int kon, int u = 1, int lo = 0, int hi = T - 1){
	push_max(u);
	if(kon < lo or hi < pocz)
		return -INF;
	if(lo >= pocz and hi <= kon)
		return tree_max[u];
	int mid = (lo + hi) / 2;
	return max(ask_max(pocz, kon, u * 2, lo, mid), ask_max(pocz, kon, u * 2 + 1, mid + 1, hi));
}

void add_max(int pocz, int kon, int val, int u = 1, int lo = 0, int hi = T - 1){
	push_max(u);
	if(kon < lo or hi < pocz)
		return;
	if(lo >= pocz and hi <= kon){
		lazy_max[u] += val;
		push_max(u);
		return;
	}
	int mid = (lo + hi) / 2;
	add_max(pocz, kon, val, u * 2, lo, mid);
	add_max(pocz, kon, val, u * 2 + 1, mid + 1, hi);
	tree_max[u] = max(tree_max[u * 2], tree_max[u * 2 + 1]);
}		

