	}else{
		add(a,(a+b)/2,c,d,e*2,f);
		add((a+b)/2+1,b,c,d,e*2+1,f);
	}
	pair<int,int> t=min(segtree[0][e*2],segtree[0][e*2+1]);
	segtree[0][e].second=t.second;
	segtree[0][e].first+=t.first;
	segtree[0][e*2].first-=t.first;
	segtree[0][e*2+1].first-=t.first;

	t=min(segtree[1][e*2],segtree[1][e*2+1]);
	segtree[1][e].second=t.second;
	segtree[1][e].first+=t.first;
	segtree[1][e*2].first-=t.first;
