template<typename T, typename F>
class SlidingWindowAggregation {
private:
	vector<T> back, front;
	vector<T> front_accum;
	T back_accum, identity;
	F merge;
public:
	SlidingWindowAggregation(F f, T id) :merge(f), identity(id) {
		back_accum = id;
		front_accum.push_back(id);
	};
	void push(T x) {
		back.push_back(x);
		back_accum = merge(back_accum, x);
	}
	bool pop() {
		if (front.size()) {
			front.pop_back();
			front_accum.pop_back();
			return true;
		}
		if (back.size() == 0)return false;
		while (back.size() != 1) {
			front.push_back(back.back());
			front_accum.push_back(merge(back.back(), front_accum.back()));
			back.pop_back();
		}
		back.pop_back();
		back_accum = identity;
		return true;
	}
	T fold_all() {
		return merge(front_accum.back(), back_accum);
	}
	int size() {
		return front.size() + back.size();
	}
};


int main() {
	ios::sync_with_stdio(false);
	std::cin.tie(0);
	std::cout.tie(0);


	string s;
	cin >> s;
	ll n = s.size();

	Array sum(n + 1, 0);
	ll mx = 0;
	REP(i, n)sum[i + 1] = sum[i] + (s[i] == '1' ? 1 : -1), chmax(mx, sum[i + 1]);
	auto f = [](P a, P b)->P {return { max(a.first,b.first),min(a.second,b.second) }; };
	P id = { -INF,INF };

	auto calc = [&](ll mx) {
		SlidingWindowAggregation<P, decltype(f)> swag(f, id);
		REP(i, n)swag.push({ sum[i + 1],sum[i + 1] });
		ll mn = 0;
		ll d = 0;
		REP(i, n) {
			auto r = swag.fold_all();
			if (s[i] == '?' && r.first + d + 2 <= mx)d += 2;
			swag.pop();
			chmin(mn, sum[i + 1] + d);
		}
		return mx - mn;
	};
	ll ans = INF;
	chmin(ans, calc(mx));
	chmin(ans, calc(mx + 1));

	cout << ans << "\n";

	return 0;
}

