struct solver
{

    solver()
    {
        string s; cin>>s;
        reverse(__all(s));
        const int n(s.size());

        auto ff=[&](const int k, bool turn)->bool
        {
            int low=0;
            int up;
            if(turn)
            {
                if(!k) return false;
                up=(k-1)/2;
            }
            else up=k/2;

            for(char d: s)
            {
                if(d=='?')
                {
                    if(turn)
                    {
                        if(up<k/2) up++;
                    }
                    else
                    {
                        if(low>0) low--;
                    }
                }
                else if(d=='1')
                {
                    if(!turn)
                    {
                        if(low>0) low--;
                        up--;
                    }
                }
                else
                {
                    if(turn)
                    {
                        if(up<k/2) up++;
                        low++;
                    }
                    else if(up>(k+1)/2-1)
                    {
                        up--;
                    }
                }
                if(low>up) return false;
                turn^=1;
            }
            return true;
        };

        auto f=[&](const int k)->bool
        {
            return ff(k,false) or ff(k,true);
        };

        cout << binary(n,-1,f) << "\n";
    }
};
