      if (s[i] == '1') {
        ++sum;
      } else if (s[i] == '0') {
        --sum;
      } else if (capacity[i] > count) {
        ++sum;
        ++count;
      } else {
        --sum;
      }
      result = min(result, sum);
    }
    return result;
  };
  cout << min(maxPrefix - solve(maxPrefix), maxPrefix + 1 - solve(maxPrefix + 1));
  return 0;
}

