	}
	for(int i=1; i<=n; ++i) {
		while(mono.size() && mono.front() < i) {
			mono.pop_front();
		}
		if(s[i-1] == '0') {
			pos = max(0, pos-1);
			neg = neg+1;
		}
		else if(s[i-1] == '1') {
			pos = pos+1;
			neg = max(0, neg-1);
		}
		else {
			j = max(i-1, j);
			while(j<=n && pref[i-1] - pref[j] + neg <= diff) {
				// add to mono
				j++;	
				if(j<=n) {
					while(mono.size() && pref[mono.back()] < pref[j]) {
						mono.pop_back();	
					}
					mono.push_back(j);
				}
			}
			assert(mono.size());
			int mx = pref[mono.front()] - pref[i-1];
			//cerr<<"mono.front(): "<<mono.front()<<' '<<mx<<' '<<j<<'\n';
			if(mx + pos +2 > diff || j==n+1) { // set to 0
				pos = max(0, pos-1);
				neg = neg+1;
			}
			else { // set to 1
				pos = pos+1;
				neg = max(0, neg-1);
			}
		}
		//cerr<<s[i-1]<<' '<<pos<<' '<<neg<<'\n';
		if(pos > diff || neg > diff) return false;
		// change the prefix
	}
	return true;
}
