struct State {
	int len;
	int minx, maxx;

	bool operator <(const State& ot) const {
		if (len != ot.len) {
			return len < ot.len;
		} else {
			return minx < ot.minx;
		}
	}
};

bool isCovered(const State& st, int x, int y) {
	if (x + y == st.len) {
		return x % 2 == st.minx % 2 && x >= st.minx && x <= st.maxx;
	} else {
		return x + y > st.len && x >= st.minx && y >= st.len - st.maxx;
	}
}

