bool check(int lim)
{
	int now1=0,now0=0;
	stack<int>Q;
	vector<int>A0(S.size()+1),A1(S.size()+1);
	lazysegtree<pair<int,int> >P(S.size()+1);
	stack<pair<int,int> >m0,m1;
	m0.push(make_pair(0,0));
	m1.push(make_pair(0,0));
	for(int i=0;i<S.size();i++)
	{
		if(S[i]=='0')
		{
			now1--;
			now0--;
			P.update(i+1,S.size()+1,-1);
		}
		else if(S[i]=='1')
		{
			now1++;
			now0++;
			P.update(i+1,S.size()+1,1);
		}
		else
		{
			now1++;
			now0--;
			Q.push(i+1);
		}
		if(now1-m1.top().first==-lim)
		{
			int id=m1.top().second;
			while(!Q.empty()&&Q.top()>id)
			{
				int j=Q.top();Q.pop();
				P.update(j,S.size()+1,1);
				now0+=2;
			}
			while(m0.top().second>id)m0.pop();
			int X=A0[id]+P.query(id,i+2).second-P.query(id,id+1).second;
			if(m0.top().first>X)m0.push(make_pair(X,id));
		}
		if(now0-m0.top().first==lim)
		{
			int id=m0.top().second;
			while(!Q.empty()&&Q.top()>id)
			{
				int j=Q.top();Q.pop();
				P.update(j,S.size()+1,-1);
				now1-=2;
			}
			while(m1.top().second>id)m1.pop();
			int X=A1[id]+P.query(id,i+2).first-P.query(id,id+1).first;
			if(m1.top().first<X)m1.push(make_pair(X,id));
		}
		if(now1-m1.top().first<-lim||now0-m0.top().first>lim)return false;
		A0[i+1]=now0;
		if(m0.top().first>now0)m0.push(make_pair(now0,i+1));
		A1[i+1]=now1;
		if(m1.top().first<now1)m1.push(make_pair(now1,i+1));
	}
	return true;
}
