      int b = 0;
      for (int i = 0; i < n; i++) {
        L1[i] = b;
        if (s[i] == '1') {
          b += 1;
        } else {
          b = max(b - 1, 0);
        }
        ans = max(ans, b);
      }
    }
    {
      int b = 0;
      for (int i = n - 1; i >= 0; i--) {
        R0[i] = b;
        if (s[i] == '0') {
          b += 1;
        } else {
          b = max(b - 1, 0);
        }
        ans = max(ans, b);
