int solve(string s){
	int n=s.length();
	t[0]=s;
	t[1]=s;
	reverse(t[1].begin(),t[1].end());
	for(int i=0;i<n;i++)if(t[1][i]!='?')t[1][i]^=('0'^'1');

	make_hoge(0,n);
	make_hoge(1,n);
	vector<int> ve[2];
	for(int i=0;i<=n;i++)if(a[0][i]+a[1][n-i]==0){
		ve[i%2].pb(i);
	//	cout<<i<<endl;
	}
	int ans=inf;
	for(int r=0;r<2;r++)if(ve[r].size()){
		if(ve[r].size()==1){
			pa z=solve(ve[r][0],n);
			ans=min(ans,max(z.first,z.second));
		}
		else{
			pa z=solve(ve[r][0],n);
			if(z.first-z.second>=0){
				ans=min(ans,z.first);
				continue;
			}
			z=solve(ve[r].back(),n);
			if(z.first-z.second<=0){
				ans=min(ans,z.second);
				continue;
			}
			int si=0,ue=ve[r].size()-1;
			while(ue-si>1){
				int me=(ue+si)/2;
				z=solve(me,n);
				if(z.first-z.second<0)si=me;
				else ue=me;
			}
			pa z1=solve(si,n),z2=solve(ue,n);
			ans=min(ans,max(z1.first,z1.second));
			ans=min(ans,max(z2.first,z2.second));

		}
	}
	return ans;
}


