const int _ = 1e6 + 7;
char str[_]; int N , preval[_];

#define mid ((l + r) >> 1)
#define lch (x << 1)
#define rch (x << 1 | 1)
int ch[_ << 2] , mx[_ << 2] , id[_ << 2] , mrk[_ << 2] , mn[_ << 2] , pid[_ << 2];
void mark(int x , int v){mx[x] += v; mn[x] += v; mrk[x] += v;}
void down(int x){if(mrk[x]){mark(lch , mrk[x]); mark(rch , mrk[x]); mrk[x] = 0;}}
void up(int x){
	mx[x] = max(mx[lch] , mx[rch]); mn[x] = min(mn[lch] , mn[rch]); id[x] = (mx[x] == mx[lch] ? id[lch] : id[rch]);
	pid[x] = min(pid[lch] , pid[rch]);
}

void init(int x , int l , int r){
	if(l == r){mx[x] = mn[x] = preval[l]; id[x] = l; pid[x] = 1e9; return;}
	init(lch , l , mid); init(rch , mid + 1 , r); up(x);
}

void setpid(int x , int l , int r , int tar , int flg){
	if(l == r){mark(x , flg ? -2 : 2); pid[x] = flg ? l : 1e9; return;}
	down(x);
	if(mid >= tar){setpid(lch , l , mid , tar , flg); mark(rch , flg ? -2 : 2);}
	else setpid(rch , mid + 1 , r , tar , flg);
	up(x);
}

int qmin(int x , int l , int r , int val){
	if(l == r) return l;
	down(x); return mx[rch] >= val ? qmin(rch , mid + 1 , r , val) : qmin(lch , l , mid , val);
}

int qsuf(int x , int l , int r , int L){
	if(l >= L) return pid[x];
	int val = qsuf(rch , mid + 1 , r , L); if(mid >= L) val = min(val , qsuf(lch , l , mid , L));
	return val;
}

int brute(){
	int mx = 0; for(int i = 1 ; i <= N ; ++i) mx = max(mx , preval[i]);
	vector < int > pot; for(int i = 0 ; i <= mx ; ++i) pot.push_back(i);
	static int sufmn[1000003]; for(int i = N ; i ; --i) sufmn[i] = max(sufmn[i + 1] + (str[i] == '1' ? 1 : -1) , 0);
	mt19937 rnd(time(0)); shuffle(pot.begin() , pot.end() , rnd); int ans = 1e9;
	for(int i = 0 ; i * N <= 1.5e8 && i < pot.size() ; ++i){
		int cur = 0 , mx = 0 , mn = 0;
		for(int j = 1 ; j <= N ; ++j){
			if(str[j] != '?') cur += (str[j] == '1' ? 1 : -1);
			else cur += (cur + 1 + sufmn[j + 1] > pot[i] ? -1 : 1);
			mx = max(mx , cur); mn = min(mn , cur);
		}
		ans = min(ans , mx - mn);
	}
	return ans;
}

