bool solveul(const string &s,int ub,int lb){
	const int n=s.size();
	int l=0,r=0;
	rep(i,n){
		if(s[i]=='1'){
			++l; ++r;
		}else if(s[i]=='0'){
			--l; --r;
		}else{
			--l; ++r;
		}
		while(l<lb) l+=2;
		while(r>ub) r-=2;
		if(l>r) return false;
		// out(i,s[i],l,r,1);
	}
	return true;
}

int solven2(const string &s){
	const int n=s.size();
	int re=n;
	rep(i,n+1)if(solveul(s,i,-n)){
		if(solveul(s,i,0)){
			MN(re,i);
			continue;
		}
		int l=0,r=n+1;
		while(r-l>1){
			int m=(l+r)/2;
			(solveul(s,i,-m)?r:l)=m;
		}
		out(i,r,1);
		MN(re,i+r);
	}
	return re;
}

