	memset(sm, 0, sizeof sm);//suffix min of prefix sums
	int g_min = 0, g_max = 0;
	for(int i = 1; i <= n; i++) {
		p[i] = p[i-1] + (s[i] == '0' ? -1 : 1);
		sm[i] = p[i];
