mt19937 rnd;

const int N   = 1 << 20;
const int T   = 2 * N;
const int INF = 1e18;

struct info {
	int minv = 0;
	int mini = 0;
	int maxv = 0;
	int maxi = 0;
};

info neutral() {
	info v;
	v.minv = +INF;
	v.mini = -1;
	v.maxv = -INF;
	v.maxi = -1;
	return v;
}

info merge(info l, info r) {
	info v;
	if (l.minv <= r.minv) {
		v.minv = l.minv;
		v.mini = l.mini;
	} else {
		v.minv = r.minv;
		v.mini = r.mini;
	}
	if (l.maxv >= r.maxv) {
		v.maxv = l.maxv;
		v.maxi = l.maxi;
	} else {
		v.maxv = r.maxv;
		v.maxi = r.maxi;
	}
	return v;
}

info tval[T];
int  tadd[T];

int ls(int v) {
	return 2 * v + 1;
}

int rs(int v) {
	return 2 * v + 2;
}

void build(int v, int l, int r) {
	tval[v].mini = l;
	tval[v].maxi = l;
	if (r - l > 1) {
		int m = (l + r) / 2;
		build(ls(v), l, m);
		build(rs(v), m, r);
	}
}

void push(int v) {
	int l = ls(v);
	int r = rs(v);
	tadd[l] += tadd[v];
	tval[l].minv += tadd[v];
	tval[l].maxv += tadd[v];
	tadd[r] += tadd[v];
	tval[r].minv += tadd[v];
	tval[r].maxv += tadd[v];
	tadd[v] = 0;
}

void upd(int v, int vl, int vr, int ql, int qr, int val) {
	if (ql <= vl && vr <= qr) {
		tadd[v] += val;
		tval[v].minv += val;
		tval[v].maxv += val;
		return;
	}
	if (qr <= vl || vr <= ql) {
		return;
	}
	push(v);
	int vm = (vl + vr) / 2;
	upd(ls(v), vl, vm, ql, qr, val);
	upd(rs(v), vm, vr, ql, qr, val);
	tval[v] = merge(tval[ls(v)], tval[rs(v)]);
}

info query(int v, int vl, int vr, int ql, int qr) {
	if (ql <= vl && vr <= qr) {
		return tval[v];
	}
	if (qr <= vl || vr <= ql) {
		return neutral();
	}
	push(v);
	int vm = (vl + vr) / 2;
	return merge(query(ls(v), vl, vm, ql, qr), query(rs(v), vm, vr, ql, qr));
}

void upd(int l, int r, int v) {
	upd(0, 0, N, l, r + 1, v);
}
pair<int, int> qmax(int l, int r) {
	auto v = query(0, 0, N, l, r + 1);
	return {v.maxv, v.maxi};
}
pair<int, int> qmin(int l, int r) {
	auto v = query(0, 0, N, l, r + 1);
	return {v.minv, v.mini};
}

