    n = s.size();
    ll now = 0, mi = 0;
    REPR(i, n - 1){
        dp[i] = now - mi;
        if (s[i] == '0') now++;
        else now--;
        mi = min(now, mi);

    }
    P res = sabu1(-1e6 - 10, 1);
    FOR(i, res.first, res.second){
        solve(i);
    }
    res = sabu2(-1e6 - 10, 1);
    FOR(i, res.first, res.second){
        solve(i);
    }
    cout << ans << endl;
}

