				ndp[j + 1] = min(ndp[j + 1], dp[j] + (j == dp[j]));
			}
			for (auto j : even) {
				if (ndp.find(j + 1) == ndp.end())ndp[j + 1] = MOD;
				ndp[j + 1] = min(ndp[j + 1], dp[j] + (j == dp[j]));
			}
		}
		if (s[i] != '1') {
			for (auto j : odd) {
				if (ndp.find(j - 1) == ndp.end())ndp[j - 1] = MOD;
				ndp[j - 1] = min(ndp[j - 1], dp[j]);
			}
			for (auto j : even) {
				if (j) {
					if (ndp.find(j - 1) == ndp.end())ndp[j - 1] = MOD;
					ndp[j - 1] = min(ndp[j - 1], dp[j]);
				}
				else {
					if (ndp.find(0) == ndp.end())ndp[0] = MOD;
					ndp[0] = min(ndp[0], dp[0] + 1);
				}
			}
		}
		int oddfst = MOD, evenfst = MOD;
		int oddeq = 0, eveneq = 0;
		for (auto j : ndp) {
			dp[j.first] = j.second;
