		even.clear();

		if (oddeq != MOD) {
			for (int j = -0; j <= 0; j += 2) {
				if (oddeq + j >= oddfst)odd.insert(oddeq + j);
			}
		}

		if (oddfst != MOD) {
			odd.insert(oddfst);
			for (int j = 0; j <= 0; j += 2) {
				odd.insert(oddfst + j);
			}
			int box = dp[oddfst];
			if (box % 2 == 0)box++;
			if (box <= oddeq) {
				dp[box] = max(box, dp[box]);
				odd.insert(box);
			}
