void fix(int &l1, int &r1, int &l2, int &r2, int B) {
	l1 = max(l1, 0);
	l2 = max(l2, 0);
	r1 = min(r1, B);
	r2 = min(r2, B);
	if (l1 % 2 != 0) l1++;
	if (l2 % 2 != 1) l2++;
	if (r1 % 2 != 0) r1--;
	if (r2 % 2 != 1) r2--;
}

bool solve(int B) {
	int l1 = 0, l2 = 0, r1 = B, r2 = B;
	fix(l1, r1, l2, r2, B);
	for (int i = 0; i < n; i++) {
		fix(l1, r1, l2, r2, B);
		if (l1 > r1) {
			l1 = N;
			r1 = -N;
		}
		if (l2 > r2) {
			l2 = N;
			r2 = -N;
		}
		fix(l1, r1, l2, r2, B);
		swap(l1, l2);
		swap(r1, r2);
		if (s[i] == '0') {
			l1--;
			l2--;
			r1--;
			r2--;
		} else if (s[i] == '1') {
			l1++;
			l2++;
			r1++;
			r2++;
		} else if (s[i] == '?') {
			l1--;
			l2--;
			r1++;
			r2++;
		} else throw;
	}
	fix(l1, r1, l2, r2, B);
	return l1 <= r1 || l2 <= r2;
}

