            case '0':
                Zbuf--;
                Zbuf0--;
                Zbuf1--;
                break;
            case '1':
                Zbuf++;
                Zbuf0++;
                Zbuf1++;
                break;
            default:
                Zbuf--;
                int MaxRight = *(csum.begin());
                if(MaxRight+Zbuf0diff+2 <= Z){
                    Zbuf0++;
                    Zbuf0diff += 2;
                }else{
                    Zbuf0--;
                }
                if(MaxRight+Zbuf1diff+2 <= Z+1){
                    Zbuf1++;
                    Zbuf1diff += 2;
                }else{
                    Zbuf1--;
                }
        }
        fZ0=min(fZ0, Zbuf0);
        fZ1=min(fZ1, Zbuf1);
        csum.erase(csum.find(Zbuf));
    }
    cout << min(Z-fZ0, Z+1-fZ1) << endl;
    return 0;
}

