template <typename T = char, typename U = string>
vector<pair<T, int>> rle(const U &s) {
  int n = s.size();
  vector<pair<T, int>> res;
  T now = s[0];
  int cnt = 1;
  FOR(i, 1, n) {
    if (s[i] != now) {
      res.emplace_back(now, cnt);
      cnt = 0;
    }
    now = s[i];
    ++cnt;
  }
  res.emplace_back(now, cnt);
  return res;
}

