    for (int i = 0; i < n; i++) {
      if (L0[i] == R1[i]) {
        ans = max(ans, L0[i] + 1);
      }
      if (L1[i] == R0[i]) {
        ans = max(ans, L1[i] + 1);
      }
      if (L0[i] + R0[i] == L1[i] + R1[i]) {
        ans = max(ans, L0[i] + R0[i] + 1);
      }
    }
    int beg = 0;
    while (beg < n) {
      if (s[beg] != '?') {
        beg += 1;
        continue;
      }
      int end = beg;
      while (end + 1 < n && s[end + 1] == '?') {
        ++end;
      }
      if ((end - beg + 1) & 1) {
        if (L0[beg] + R0[end] == L1[beg] + R1[end]) {
          ans = max(ans, L0[beg] + R0[end] + 1);
        }
//        debug(L0[beg], L1[beg], R0[end], R1[end]);
      }
      beg = end + 1;
    }
    for (int r = 0; r < 2; r++) {
      vector<int> by_diff(2 * n + 1, -1);
      for (int i = r; i < n; i += 2) {
        int cur = L0[i] - L1[i] + n;
        by_diff[cur] = max(by_diff[cur], L0[i]);
        cur = R1[i] - R0[i] + n;
        if (by_diff[cur] >= 0) {
          ans = max(ans, L0[i] + by_diff[cur] + 1);
        }
      }
    }
    for (int i = 0; i < n; i++) {
      if (s[i] == '?') {
        if (L0[i] == ans || R0[i] == ans) {
          s[i] = '1';
        }
        if (L1[i] == ans || R1[i] == ans) {
          s[i] = '0';
        }
      }
    }
//    debug(s);
  }
  cout << ans << '\n';
  return 0;
}

