    STR(s);
    if(all_of(all(s),[](char c){return c=='?';}))return out(1);
    while(s.back()=='?')s.pop_back();
    const ll n=s.size();
    LazySegmentTree seg(n+1);
    rep(n+1)seg.set(i,pll());
    vector<ll>q;
    rep(n){
        if(s[i]=='?')q.push_back(i);
        elif(s[i]=='0'){
            seg.query(i+1,n+1,-1);
            if(q.size()&&seg[i+1]<seg.get(0,i+1).first){
                ll i=q.back();
                q.pop_back();
                seg.query(i+1,n+1,1);
            }
        }
        else{
            seg.query(i+1,n+1,1);
            if(q.size()&&seg[i+1]>seg.get(0,i+1).second){
                ll i=q.back();
                q.pop_back();
                seg.query(i+1,n+1,-1);
            }
        }
    }
    each(i,q){
        seg.query(i+1,n+1,-1);
        auto [mn1,mx1]=seg.data[1];
        seg.query(i+1,n+1,2);
        auto [mn2,mx2]=seg.data[1];
        if(mx1-mn1<mx2-mn2)seg.query(i+1,n+1,-2);
    }
    auto [mn,mx]=seg.data[1];
    out(mx-mn);
