struct Tree{
	int BOTTOM;
	VI u;
	std::vector<PII> mx, mn;

	void build(VI A){
		BOTTOM = 1;
		while(BOTTOM < SZ(A)) BOTTOM *= 2;
		mx.resize(BOTTOM*2, MP(-INF, 1));
		mn.resize(BOTTOM*2, MP(INF, 1));
		u.resize(BOTTOM*2);

		FOR(i, SZ(A)) mn[i+BOTTOM] = mx[i+BOTTOM] = MP(A[i], -i);
		for(int i = BOTTOM-1; i >= 1; --i){
			mn[i] = std::min(mn[i<<1], mn[(i<<1)+1]);
			mx[i] = std::max(mx[i<<1], mx[(i<<1)+1]);
		}
	}

	void upd(int v){
		mn[v].X += u[v];
		mx[v].X += u[v];
		if(v < BOTTOM){
			u[v<<1] += u[v];
			u[(v<<1)+1] += u[v];
		}
		u[v] = 0;
	}

	PII max(int a, int b, int v=1, int lo=0, int hi=-2){
		if(hi==-2) hi = BOTTOM-1;
		upd(v);
		if(a > b) return MP(-INF, 1);
		if(a == lo && b == hi){
			return mx[v];
		}
		int mid = (lo+hi)/2;
		return std::max(max(a, std::min(b, mid), v<<1, lo, mid),
						max(std::max(a, mid+1), b, (v<<1)+1, mid+1, hi));
	}

	PII min(int a, int b, int v=1, int lo=0, int hi=-2){
		if(hi==-2) hi = BOTTOM-1;
		upd(v);
		if(a > b) return MP(INF, 1);
		if(a == lo && b == hi){
			return mn[v];
		}
		int mid = (lo+hi)/2;
		return std::min(min(a, std::min(b, mid), v<<1, lo, mid),
						min(std::max(a, mid+1), b, (v<<1)+1, mid+1, hi));
	}

	void update(int a, int b, int w, int v=1, int lo=0, int hi=-2){
		if(hi == -2) hi = BOTTOM-1;
		upd(v);
		if(a > b) return;
		if(a == lo && b == hi){
			u[v] += w;
			upd(v);
			return;
		}
		int mid = (lo+hi)/2;
		update(a, std::min(b, mid), w, v<<1, lo, mid);
		update(std::max(a, mid+1), b, w, (v<<1)+1, mid+1, hi);
		mn[v] = std::min(mn[v<<1], mn[(v<<1)+1]);
		mx[v] = std::max(mx[v<<1], mx[(v<<1)+1]);
	}
};

