            int ok = 1;
            if (tmp > now) ok = -1;
            for (int q = i + 1; q < s.length(); ++q) {
                if (s[q] == '1') {
                    tmp++;
                }
                else {
                    tmp--;
                }
                if (tmp > now) ok = -1;
            }
            start += ok;
        }
        ans = min(ans, start);
    }
    return ans;
