        else {
            now--;
        }
        bot = max(bot, now);
    }
    int top = s.length() + 1;
    while (top - bot > 3) {
        int mid1 = (bot + bot + top) / 3;
        int mid2 = (bot + top + top) / 3;
        if (mid1 - val(mid1) < mid2 - val(mid2)) {
            top = mid2;
        }
        else {
            bot = mid1;
        }
    }
    top += 2;
    int ans = 1e9;
    for (int i = bot; i <= top; ++i) {
        ans = min(ans, i - val(i));
    }
