	if(u.pos==v.pos)return mp(node(min(u.L,v.L),max(u.R,v.R),u.pos),node(-1,-1,-1));
	else if(z.R-z.L>=1)
	{
		if(u.pos<v.pos)return mp(u,node(-1,-1,-1));
		else return mp(v,node(-1,-1,-1));
	}
	else return mp(u,v);
}
void trans1()
{
	las.clear();
	for(auto p:vec)las.emplace_back(move2(p));
	vec=las;
}
void trans0()
{
	las.clear();
	for(auto p:vec)las.emplace_back(move3(p));
	vec=las;
}
bool cmp(node n1,node n2)
{
	if(n1.L!=n2.L)return n1.pos<n2.pos;
	return n1.pos<n2.pos;
}
void trans2()
{
	las.clear();one.clear();
	for(auto p:vec)
	{
		pair<node,node> T=move1(p);
		if(T.second.L==-1)
		{
			node z=T.first;
			if(z.R-z.L>=1)las.emplace_back(z);
			else one.emplace_back(z);
		}
		else one.emplace_back(T.first),one.emplace_back(T.second);
	}
	sort(one.begin(),one.end(),cmp);
	int lasx=0;
	for(auto p:one)
	{
		if(p.L!=lasx)las.emplace_back(p);
		lasx=p.L;
	}vec=las;
}
