		ri[at[i]]=min(ri[at[i]],mid-sum[i]);
	}
	if(le[0]>ri[0])return false;
	int l,r,ty;
	if(le[0]==ri[0]){
		l=r=le[0];
		ty=(le[0]%2);
	}else{
		l=le[0];r=ri[0];
		ty=2;
	}
	for(int i=1;i<=cnt;++i){
		if(ty==2){
			l--;r++;
			l=max(l,le[i]);r=min(r,ri[i]);
			if(l>r)return false;
			if(l==r){
				ty=(l%2);
				continue;
			}
