int solve(){
	int f, l, r, lx, ly, rx, ry;
	f = 0, l = 0, r = 0;
	lx = 0, ly = 0;
	rx = 0, ry = 0;
	for (int i = 1; i <= n; i++){
		if (s[i] == '0'){
			l = max(0, l - 1); r--;
			lx = max(0, lx - 1);
			ly = ly + 1;
			rx = max(0, rx - 1);
			ry = ry + 1;
			if (r < 0) l = r = rx, f = rx + ry;
		}
		if (s[i] == '1'){
			l++, r = min(f, r + 1);
			lx = lx + 1;
			ly = max(0, ly - 1);
			rx = rx + 1;
			ry = max(0, ry - 1);
			if (l > f) l = r = lx, f = lx + ly;
		}
		if (s[i] == '?'){
			lx = max(0, l - 1);
			ly = f - l + 1;
			rx = r + 1;
			ry = max(0, f - r - 1);
			l--; if (l < 0) l += 2;
			r++; if (r > f) r -= 2;
		}
		if (l == lx) ly = min(ly, f - l);
		if (f - r == ry) rx = min(rx, r);
	}
	return f;
}
int main(){
	scanf("\n%s", s + 1);
	n = strlen(s + 1); 
	int ans;
	if (s[1] == '?'){
		s[1] = '0';
		ans = solve();
		s[1] = '1';
		ans = min(ans, solve());
	}
	else ans = solve();
	cout << ans << endl;
    return 0;
}

