int substr(char* t, const char* s, int pos, int len)
{
    if (pos < 0 || len < 0 || len > strlen(s))
        return -1;
    for (s += pos; *s != '\0' && len > 0; len--)
        *t++ = *s++;
    *t = '\0';
    return 0;
}

int avsolute(int v)
{
    return v < 0 ? v * -1 : v;
}

int unbalance(char* s) 
{
    int ls= strlen(s);
    int un = 0;
    char* ss = (char*)malloc(sizeof(char) * ls);

    for (int r = 1; r != ls; r++)
    {
        for (int l = 0; l != r; l++)
        {
            substr(ss, s, l, r);

            if (un < avsolute(strchnum(ss, one) - strchnum(ss, zero)))
            {
                un = avsolute(strchnum(ss, one) - strchnum(ss, zero));
            }
        }
    }
    return un;
}


