template<class num_t> struct SegmentTree {
    int n;
    vector<pair<num_t, num_t>> st;
    vector<pair<num_t, num_t>> st2;
    vector<num_t> lz;
    void init(int n_) {
        n = n_;
        st.resize(n << 2);
        st2.resize(n << 2);
        lz.resize(n << 2);
    }
    void build(int p, int L, int R) {
        if (L == R) {
            st[p].se = st2[p].se = L;
            return;
        }
        build(p << 1, L, L + R >> 1);
        build(p << 1 | 1, (L + R >> 1) + 1, R);
    }
    void push(int p, int L, int R) {
        if (lz[p]) {
            st[p].fi += lz[p];
            st2[p].fi += lz[p];
            if (L < R) {
                lz[p << 1] += lz[p];
                lz[p << 1 | 1] += lz[p];
            }
            lz[p] = 0;
        }
    }
    void upd(int p, int l, int r, int L, int R, num_t val) {
        push(p, L, R);
        if (r < L || R < l) return;
        if (l <= L && R <= r) {
            lz[p] = val;
            push(p, L, R);
            return;
        }
        upd(p << 1, l, r, L, L + R >> 1, val);
        upd(p << 1 | 1, l, r, (L + R >> 1) + 1, R, val);
        st[p] = min(st[p << 1], st[p << 1 | 1]);
        st2[p] = max(st2[p << 1], st2[p << 1 | 1]);
    }
    void upd(int l, int r, num_t val) {
        upd(1, l, r, 0, n - 1, val);
    }
};
SegmentTree<int> seg;

void chemthan() {
    string s; cin >> s;
    int n = sz(s);
    seg.init(n);
    seg.build(1, 0, n - 1);
    FOR(i, 0, n) {
        if (s[i] == '1') {
            seg.upd(i, n - 1, +1);
        }
        else {
            seg.upd(i, n - 1, -1);
        }
    }
    auto calc = [&] () {
        return max(0, seg.st2[1].fi) - min(0, seg.st[1].fi);
    };
    vi fen(n + 1);
    auto upd = [&] (int p, int v) {
        p++;
        for ( ; p < sz(fen); p += p & -p) {
            fen[p] += v;
        }
    };
    auto query = [&] (int p) {
        p++;
        int res = 0;
        for (; 0 < p; p -= p & -p) {
            res += fen[p];
        }
        return res;
    };
    auto calc1 = [&] (int x) {
        int lo = -1, hi = x;
        int t = query(x);
        while (lo < hi) {
            int mi = lo + hi + 1 >> 1;
            if (query(mi - 1) < t) {
                lo = mi;
            }
            else {
                hi = mi - 1;
            }
        }
        return lo + hi >> 1;
    };
    auto calc2 = [&] (int x) {
        int lo = x + 1, hi = n;
        int t = query(x);
        while (lo < hi) {
            int mi = lo + hi >> 1;
            if (query(mi) - t == mi - x) {
                lo = mi + 1;
            }
            else {
                hi = mi;
            }
        }
        return lo + hi >> 1;
    };
    int res = calc();
    FOR(i, 0, n) if (s[i] == '?') {
        upd(i, 1);
    }
    FOR(it, 0, 8 * n) {
        int t = seg.st[1].se;
        int t2 = calc1(t);
        if (t2 == -1) break;
        upd(t2, -1);
        seg.upd(t2, n - 1, 2);
        int t3 = calc2(t2);
        if (t3 < n) {
            upd(t3, 1);
            seg.upd(t3, n - 1, -2);
        }
        chkmin(res, calc());
    }
    cout << res << "\n";
}

