const int INF = 1e9;
int solve(string s, int up) {
    int n = s.size();
    vector <int> pref(n + 1);
    for (int i = 0; i < n; ++i) {
        int x;
        if (s[i] == '1')
            x = 1;
        else
            x = -1;

        pref[i + 1] = pref[i] + x;            
    }   

    vector <int> suff(n + 1, -INF);
    for (int i = n - 1; i >= 0; --i)
        suff[i] = max(suff[i + 1], pref[i + 1]);

    int rem = 0, cur = 0;
    int mn = 0;
    for (int i = 0; i < n; ++i) {
        if (s[i] == '?') {
            if (suff[i] + 2 * (rem + 1) <= up) {
                ++rem;
                ++cur;
            }   
            else {
                --cur;
            }   
        }   
        else if (s[i] == '1') {
            ++cur;
        }   
        else {
            --cur;
        }   

        //cout << "cur : " << cur << endl;

        mn = min(mn, cur);
    }
    return up - mn;
}   

