bool check(int len) {
  int l = 0, r = len;
  bool odd = false;
  for (int i = 0; i < n; i++) {
    if (s[i] == '0') {
      l--;
      r--;
    } else if (s[i] == '1') {
      l++;
      r++;
    } else {
      l--;
      r++;
    }
    if (l < 0) {
      l += 1 + (int) odd;
    }
    if (r > len) {
      r -= 1 + (int) odd;
    }
    if (l > r) {
      return false;
    }
    if (l == r) {
      odd = true;
    }
  }
  return true;
}

