struct st {
	vector<int> t, mod;
	int n;

	void build(int *a, int v, int tl, int tr) {
		if (tl == tr) {
			t[v] = a[tl];
		} else {
			int tm = (tl + tr) >> 1;
			build(a, v * 2, tl, tm);
			build(a, v * 2 + 1, tm + 1, tr);
			t[v] = max(t[v * 2], t[v * 2 + 1]);
		}
	}

	st(int *a, int _n) {
		n = _n;
		t.resize(4 * n);
		mod.resize(4 * n);
		build(a, 1, 0, n - 1);
		// output(all(t));
	}

	void add(int l, int r, int val, int v, int tl, int tr) {
		if (r < tl || tr < l) {
			return;
		}
		if (l <= tl && tr <= r) {
			mod[v] += val;
			t[v] += val;
		} else {
			int tm = (tl + tr) >> 1;
			add(l, r, val, v * 2, tl, tm);
			add(l, r, val, v * 2 + 1, tm + 1, tr);
			t[v] = max(t[v * 2], t[v * 2 + 1]) + mod[v];
		}
	}

	void add(int l, int r, int val) {
		add(l, r, val, 1, 0, n - 1);
	}

	int get_max() {
		return t[1];
	}
};

