const int N = 1e6 + 5;

int n;
string s;

int low[N];

int check(int ub){
    int lb = 0, curr = 0;
    FOR(i,n){
        if(s[i] == '1'){
            curr++;
        }else if(s[i] == '0'){
            curr--;
        }else{
            // if pick 1 is safe
            if(curr + 1 + low[i+1] <= ub){
                curr++;
            }else{
                curr--;
            }
        }
        lb = min(lb, curr);
    }
    // printf("check lb %d, ub %d = %d\n",lb,ub,ub-lb);
    return ub - lb;
}

int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    #define endl '\n'
    cout.setf(ios::fixed);
    cout.setf(ios::showpoint);
    cout.precision(10);

    cin>>s;
    n = s.size();

    low[n] = 0;
    FORD(i,n){
        char c = s[i];
        if(c == '?')c = '0';

        low[i] = low[i+1];
        if(c == '1') low[i]++;
        else low[i] = max(0, low[i]-1);
    }

    // FOR(i,n)printf("%d ",low[i]);printf("\n");

    int lo = low[0], hi = 1e6;
    int ans = OO;
    while(hi - lo >= 10){
        int mid1 = (lo+lo+hi)/3;
        int mid2 = (lo+hi+hi)/3;
        int v1 = check(mid1);
        int v2 = check(mid2);

        ans = min(ans, v1);
        ans = min(ans, v2);

        if(v1 < v2){
            hi = mid2;
        }else{
            lo = mid1;
        }
    }

    REP(i,lo,hi){
        ans = min(ans, check(i));
    }

    cout << ans << endl;

    // REP(i,lo,lo+10)printf("check ub %d = %d\n",i,check(i));

    return 0;
}

