auto chmin = [](auto&& a, auto b) { return b < a ? a = b, 1 : 0; };
auto chmax = [](auto&& a, auto b) { return a < b ? a = b, 1 : 0; };

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  string s;
  cin >> s;
  int n = size(s);
  vector<int> h0(n + 1), h1(n + 1);
  for (int i = 0; i < n; ++i) {
    h0[i + 1] = h0[i] + (s[i] != '1' ? 1 : -1);
    h1[i + 1] = h1[i] + (s[i] == '0' ? 1 : -1);
  }
  int mx0 = 0, mxi = 0;
  vector<pair<int, int>> lr0{{0, 0}};
  for (int i = 0; i < n; ++i) {
    if (h0[i + 1] >= h0[mxi]) {
      mxi = i + 1;
    }
    int cur = h0[mxi] - h0[i + 1];
    if (cur < mx0) continue;
    if (cur > mx0) {
      mx0 = cur;
      lr0.clear();
    }
    lr0.emplace_back(mxi, i + 1);
  }
  int mx1 = 0, mni = 0;
  vector<pair<int, int>> lr1{{0, 0}};
  for (int i = 0; i < n; ++i) {
    if (h1[i + 1] <= h1[mni]) {
      mni = i + 1;
    }
    int cur = h1[i + 1] - h1[mni];
    if (cur < mx1) continue;
    if (cur > mx1) {
      mx1 = cur;
      lr1.clear();
    }
    lr1.emplace_back(mni, i + 1);
  }
  for (auto [l, r] : lr0) {
    for (int i = l; i < r; ++i) {
      if (s[i] == '?') {
        s[i] = '0';
      }
    }
  }
  for (auto [l, r] : lr1) {
    for (int i = l; i < r; ++i) {
      if (s[i] == '?') {
        s[i] = '1';
      }
    }
  }
  int m = max(mx0, mx1);
  int t = 0, mnt = 0, mnti = 0, mxt = 0, si = -1;
  for (int i = 0; i < n; ++i) {
    if (s[i] == '0') {
      ++t;
    } else if (s[i] == '1') {
      --t;
    } else {
      t = mnt = mxt = 0;
      mnti = i + 1;
      continue;
    }
    if (t - mnt == m) {
      si = mnti;
      break;
    }
    if (mxt - t == m) {
      si = i + 1;
      break;
    }
    if (chmin(mnt, t)) {
      mnti = i + 1;
    }
    chmax(mxt, t);
  }
  int l = 0, r = 0;
  bool ok = true;
  for (int i = si; i < n; ++i) {
    if (s[i] == '0') {
      ++l, ++r;
    } else if (s[i] == '1') {
      --l, --r;
    } else {
      --l, ++r;
    }
    while (l < 0) {
      l += 2;
    }
    while (r > m) {
      r -= 2;
    }
    if (l > r) {
      ok = false;
      break;
    }
  }
  l = 0, r = 0;
  for (int i = si; i--; ) {
    if (s[i] == '0') {
      --l, --r;
    } else if (s[i] == '1') {
      ++l, ++r;
    } else {
      --l, ++r;
    }
    while (l < 0) {
      l += 2;
    }
    while (r > m) {
      r -= 2;
    }
    if (l > r) {
      ok = false;
      break;
    }
  }
  cout << (m + not ok) << '\n';
}

