vector<ll> c;
void init() {
	c.resize(n + 1);
	int tmp = 0;
	vector<ll> memo(n + 1);
	memo[0] = 0;
	rep(i, s.size()) {
		if (s[i] == '0')tmp--;
		else tmp++;
		memo[i + 1] = tmp;
	}
	ll mi = memo[n];
	per(i, n + 1) {
		mi = min(mi, memo[i]);
		c[i] = memo[i] - mi;
	}

}
int calc(int inf) {
	int ma = 0;
	int tmp = 0;
	rep(i, n) {
		if (s[i] == '0')tmp--;
		else if (s[i] == '1')tmp++;
		else {
			if (tmp - 1 - c[i + 1] >= inf) {
				tmp--;
			}
			else tmp++;
		}
		ma = max(ma, tmp);
	}
	return ma - inf;
}

void solve() {
	cin >> s;
	n = s.size();
	init();
	int le = -n - 1, ri = -c[0]+1;
	while (ri - le > 1) {
		int m = (le + ri) / 2;
		int c1 = calc(m);
		int c2 = calc(m - 2);
		if (c1 < c2) {
			le = m;
		}
		else {
			ri = m;
		}
	}
	int ans = n;
	for (int i = -2; i <= 2; i++) {
		if (i + ri <= -c[0]) {
			ans = min(ans, calc(i + ri));
		}
	}
	cout << ans << "\n";
}

