string s;
int val(int now) {
    int ans = 0;
    int start = 0;
    REP(i, s.length()) {
        if (s[i] == '1') {
            start++;
        }
        else if (s[i] == '0') {
            start--;
        }
        else {
            int tmp = start + 1;
            int ok = 1;
            if (tmp > now) ok = -1;
            for (int q = i + 1; q < s.length(); ++q) {
                if (s[q] == '1') {
                    tmp++;
                }
                else {
                    tmp--;
                }
                if (tmp > now) ok = -1;
            }
            start += ok;
        }
        ans = min(ans, start);
    }
    return ans;
}
void solve(){
    cin >> s;
    if (s.length() > 1000) return;
    int bot = 0;
    int now = 0;
    REP(i, s.length()) {
        if (s[i] == '1') {
            now++;
        }
        else {
            now--;
        }
        bot = max(bot, now);
    }
    int top = s.length() + 1;
    while (top - bot > 3) {
        int mid1 = (bot + bot + top) / 3;
        int mid2 = (bot + top + top) / 3;
        if (mid1 - val(mid1) < mid2 - val(mid2)) {
            top = mid2;
        }
        else {
            bot = mid1;
        }
    }
    top += 2;
    int ans = 1e9;
    for (int i = bot; i <= top; ++i) {
        ans = min(ans, i - val(i));
    }
    cout << ans << endl;
}
