struct tour {
  int mn, mx, prop;
} t[2*TOUR];

void propagiraj(int pos) {
  FOR(i, 2*pos, 2*pos+2) {
    t[i].mn += t[pos].prop;
    t[i].mx += t[pos].prop;
    t[i].prop += t[pos].prop;
  }
  t[pos].prop = 0;
}

void update(int pos) {
  t[pos].mn = min(t[2*pos].mn, t[2*pos+1].mn);
  t[pos].mx = max(t[2*pos].mx, t[2*pos+1].mx);
}

int get_first_min(int pos, int lo, int hi, int val) {
  if (lo + 1 == hi) return lo;

  propagiraj(pos);
  if (t[2*pos].mn <= val) return get_first_min(2*pos, lo, (lo+hi)/2, val);
  return get_first_min(2*pos+1, (lo+hi)/2, hi, val);
}

void increase(int pos, int lo, int hi, int begin, int end, int val) {
  if (lo >= end || hi <= begin) return;
  if (lo >= begin && hi <= end) {
    t[pos].mn += val;
    t[pos].mx += val;
    t[pos].prop += val;
    return;
  }

  propagiraj(pos);
  increase(2*pos+0, lo, (lo+hi)/2, begin, end, val);
  increase(2*pos+1, (lo+hi)/2, hi, begin, end, val);

  update(pos);
}

