    pref[i+1] = pref[i] + (s[i] == '1' ? 1 : -1);

  REP(i, n+1) t[TOUR+i].mn = t[TOUR+i].mx = pref[i];
  FOR(i, n+1, TOUR) {
    t[TOUR+i].mn = 1e9;
    t[TOUR+i].mx = -1e9;
  }

  for (int i=TOUR-1; i; i--)
    update(i);
}

int main()
{
