  init();

  int sol = -t[1].mn + t[1].mx;

  for(;;) {
    int pos = get_first_min(1, 0, TOUR, t[1].mn + 1);
    auto its = S.lower_bound(pos);
    if (its == S.end() || *its > pos) {
      if (its != S.begin())
        its--;
    }

    if (its == S.end() || *its > pos) {
      pos = get_first_min(1, 0, TOUR, t[1].mn);
