unordered_map<unsigned long long, int> used(1e7);

void go(int i, int a, int b) {
    int cand = a + b;
    if (cand >= record) return;
    if (i == n+1) {
        record = cand;
        return;
    }
    unsigned long long h = (((unsigned long long) i) << 32) + a;
    auto it = used.find(h);
    if (it != used.end()) {
        int ob = it->second;
        if (ob <= b) return;
    }
    used[h] = b;
    char c = s[i];
    if (c == '0') {
        if (a == 0) {
            go(i+1, 0, b+1);
        } else {
            go(i+1, a-1, b+1);
        }
    } else if (c == '1') {
        if (b == 0) {
            go(i+1, a+1, 0);
        } else {
            go(i+1, a+1, b-1);
        }
    } else {
        if (a > b) {
            if (a == 0) {
                go(i+1, 0, b+1);
            } else {
                go(i+1, a-1, b+1);
            }
            if (b == 0) {
                go(i+1, a+1, 0);
            } else {
                go(i+1, a+1, b-1);
            }
        } else {
            if (b == 0) {
                go(i+1, a+1, 0);
            } else {
                go(i+1, a+1, b-1);
            }
            if (a == 0) {
                go(i+1, 0, b+1);
            } else {
                go(i+1, a-1, b+1);
            }
        }
    }
}

