				while(m0.top().second>id)m0.pop();
				int X=A0[id]+P.query(id,i+2).second-P.query(id,id+1).second;
				if(m0.top().first>X)m0.push(make_pair(X,id));
				f1=false;
				f2=true;
			}
			else
			{
				int id=m0.top().second;
				while(!Q.empty()&&Q.top()>id)
				{
					int j=Q.top();Q.pop();
					P.update(j,S.size()+1,make_pair(-1,0));
					now1-=2;
				}
				while(m1.top().second>id)m1.pop();
				int X=A1[id]+P.query(id,i+2).first-P.query(id,id+1).first;
				if(m1.top().first<X)m1.push(make_pair(X,id));
				f2=false;
				f1=true;
			}
		}
		if(now1-m1.top().first<-lim||now0-m0.top().first>lim)return false;
		A0[i+1]=now0;
		if(m0.top().first>now0)m0.push(make_pair(now0,i+1));
		A1[i+1]=now1;
		if(m1.top().first<now1)m1.push(make_pair(now1,i+1));
	}
	return true;
}
