int calc(string S) {
	int N = S.size();
	int ans = 0;
	REP(l, N) {
		FOR(r, l + 1, N+1) {
			int c0 = 0, c1 = 0;
			FOR(i, l, r) {
				if (S[i] == '0')c0++;
				else c1++;
			}
			chmax(ans, abs(c0 - c1));
		}
	}
	return ans;
}

int naive(string S) {
	int cnt = 0;
	int N = S.size();
	int mn = S.size();
	vector<int>pos;
	REP(i, N)if (S[i] == '?') {
		pos.push_back(i);
		cnt++;
	}
	REP(bit, 1 << cnt) {
		string s = S;
		REP(i, cnt) {
			if (bit&(1 << i)) {
				s[pos[i]] = '1';
			}
			else s[pos[i]] = '0';
		}
		//DEBUG(s);
		//DEBUG(calc(s));
		mn = min(mn, calc(s));
	}
	//if (cnt == 0)mn = calc(S);
	return mn;
}

int solve_(string s) {
	//mt.seed((int)(time(0)));
	S = s;
	T = S;
	N = S.size();
	int ok = N, ng = 0;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		//DEBUG(mid);
		if (check(mid)||check2(mid)||check3(mid)||check3(mid)||check3(mid)||check3(mid)||check3(mid)||check3(mid))ok = mid;
		else ng = mid;
	}
	return ok;
}

