bool solve(string &s,ll lim){
  vector<P>p(1,MP(0,0));
  ll n=s.size();
  rep(i,0,n){
    vector<P>tmp;
    for(auto z:p){
      if(s[i]!='1')tmp.EB(z.fi+1,max(0LL,z.se-1));
      if(s[i]!='0')tmp.EB(max(0LL,z.fi+-1),z.se+1);
    }
    ll sz=tmp.size();
    vector<bool>t(sz,true);
    rep(i,0,sz)if(max(tmp[i].fi,tmp[i].se)>lim)t[i]=false;
    rep(i,0,sz)rep(j,i+1,sz){
      if(tmp[i].fi>=tmp[j].fi&&tmp[i].se>=tmp[j].se)t[j]=false;
      if(tmp[i].fi<tmp[j].fi&&tmp[i].se<tmp[j].se)t[i]=false;
    }
    //debug(tmp,sz);
    p.clear();
    rep(i,0,sz)if(t[i])p.EB(tmp[i]);
  }
  return !p.empty();
}
