int work(int limit) {
	int mns = 0;
	for (int i = 1; i <= n; i++) {
		if (s[i] == '?' && sMin[i] - mns - 2 >= limit) {
			b[i] = false;
			mns += 2;
		} 
		a[i] -= mns;
	}
	sMin[n + 1] = n + 5;
	sMax[n + 1] = -n - 5;
	for (int i = n; i >= 0; i--) {
		sMin[i] = min(sMin[i + 1], a[i]);
		sMax[i] = max(sMax[i + 1], a[i]);
	}
	int ans = sMax[0] - sMin[0];
	int Max = 0, Min = 0, pls = 0; mns = 0;
	for (int i = 1; i <= n; i++) {
		if (b[i]) {
			mns += 2;
			int tmp = max(Max, sMax[i] - mns) - min(Min, sMin[i] - mns);
			if (tmp < ans) ans = tmp;
		}
		a[i] -= mns;
		chkmax(Max, a[i]);
		chkmin(Min, a[i]);
	}
	return ans;
}
