int mx[N<<2], mn[N<<2], tg[N<<2];
inline void psh(int x,int s){
	tg[x]+=s;mx[x]+=s,mn[x]+=s;
}
inline void pd(int x,int l,int r){
	if(tg[x]){
		if(l^r)psh(x<<1,tg[x]),psh(x<<1|1,tg[x]);
		tg[x]=0;
	}
}

inline void add(int x,int l,int r,int ql,int qr,int s){
	pd(x,l,r);
	if(ql<=l&&qr>=r){
		psh(x,s);
		return ;
	}
	int mid=(l+r)>>1;
	if(ql<=mid)add(x<<1,l,mid,ql,qr,s);
	if(qr>mid)add(x<<1|1,mid+1,r,ql,qr,s);
	mx[x]=max(mx[x<<1],mx[x<<1|1]);
	mn[x]=min(mn[x<<1],mn[x<<1|1]);
}

inline int find(int x,int l,int r){
	pd(x,l,r);
	if(l==r)return l;
	int mid=(l+r)>>1;
	if(mx[x<<1]==mx[x])return find(x<<1,l,mid);
	else return find(x<<1|1,mid+1,r);
}

inline int findr(int x,int l,int r){
	pd(x,l,r);
	if(l==r)return l;
	int mid=(l+r)>>1;
	// cerr << l << "to" << r << "," << mx[x<<1|1] << "?" << mx[x] << endl;
	if(mx[x<<1|1]!=mx[x])return findr(x<<1,l,mid);
	else return findr(x<<1|1,mid+1,r);
}

