template<class num_t> struct SegmentTree {
    int n;
    vector<pair<num_t, num_t>> st;
    vector<pair<num_t, num_t>> st2;
    vector<num_t> lz;
    void init(int n_) {
        n = n_;
        st.resize(n << 2);
        st2.resize(n << 2);
        lz.resize(n << 2);
    }
    void build(int p, int L, int R) {
        if (L == R) {
            st[p].se = st2[p].se = L;
            return;
        }
        build(p << 1, L, L + R >> 1);
        build(p << 1 | 1, (L + R >> 1) + 1, R);
    }
    void push(int p, int L, int R) {
        if (lz[p]) {
            st[p].fi += lz[p];
            st2[p].fi += lz[p];
            if (L < R) {
                lz[p << 1] += lz[p];
                lz[p << 1 | 1] += lz[p];
            }
            lz[p] = 0;
        }
    }
    void upd(int p, int l, int r, int L, int R, num_t val) {
        push(p, L, R);
        if (r < L || R < l) return;
        if (l <= L && R <= r) {
            lz[p] = val;
            push(p, L, R);
            return;
        }
        upd(p << 1, l, r, L, L + R >> 1, val);
        upd(p << 1 | 1, l, r, (L + R >> 1) + 1, R, val);
        st[p] = min(st[p << 1], st[p << 1 | 1]);
        st2[p] = max(st2[p << 1], st2[p << 1 | 1]);
    }
    void upd(int l, int r, num_t val) {
        upd(1, l, r, 0, n - 1, val);
    }
};
SegmentTree<int> seg;

void chemthan() {
    string s; cin >> s;
    int n = sz(s);
    seg.init(n);
    seg.build(1, 0, n - 1);
    FOR(i, 0, n) {
        if (s[i] == '1') {
            seg.upd(i, n - 1, +1);
        }
        else {
            seg.upd(i, n - 1, -1);
        }
    }
    auto calc = [&] () {
        return max(0, seg.st2[1].fi) - min(0, seg.st[1].fi);
    };
    int res = calc();
    set<int> st, st2;
    FOR(i, 0, n) if (s[i] == '?') {
        st.insert(i);
    }
    while (sz(st)) {
        int t = seg.st[1].se;
        auto it = st.upper_bound(t);
        if (it == st.begin()) {
            break;
        }
        it--;
        t = *it;
        st.erase(t);
        st2.insert(t);
        seg.upd(t, n - 1, 2);
        it = st2.upper_bound(t);
        if (it != st2.end()) {
            t = *it;
            seg.upd(t, n - 1, -2);
            st.insert(t);
        }
        chkmin(res, calc());
    }
    cout << res << "\n";
}

