int Rec(int i, int vmax, int vmin, int v){
  static map<tuple<int,int,int,int>,int> mp;
  if(mp.count({i,vmax,vmin,v}) > 0) return mp[{i,vmax,vmin,v}];
  vmax = max(vmax,v);
  vmin = min(vmin,v);
  if(i >= len){
    return mp[{i,vmax,vmin,v}] = vmax - vmin;
  }
  if(s[i] == '0'){
    return mp[{i,vmax,vmin,v}] = Rec(i+1,vmax,vmin,v-1);
  } else if(s[i] == '1'){
    return mp[{i,vmax,vmin,v}] = Rec(i+1,vmax,vmin,v+1);
  }
  return mp[{i,vmax,vmin,v}] = min(Rec(i+1,vmax,vmin,v+1),Rec(i+1,vmax,vmin,v-1));
}

