};


const int M = 1 << 20;
Node drz[2 * M + 5];

void Shift(int son, int val) {
  drz[son].mi += val;
  drz[son].ma += val;
  drz[son].to_push += val;
}

void Touch(int v) {
  FOR (son, 2 * v, 2 * v + 1) {
    Shift(son, drz[v].to_push);
  }
  drz[v].to_push = 0;
}
Node Merge(Node L, Node R) {
  Node n;
  n.mi = min(L.mi, R.mi);
  n.ma = max(L.ma, R.ma);
  if (L.ma >= R.ma) {
    n.wh_ma = L.wh_ma;
  } else {
    n.wh_ma = R.wh_ma;
  }
  n.to_push = 0;
  //n.suf_mi
  //n.sum = L.sum + R.sum;
  //   n.mi = min({L.mi, R.mi, n.pref_mi});
  //   n.ma = max(
  return n;
}
void Add(int bl, int br, int l, int r, int v, int val) {
  if (bl > r || br < l) { return; }
  if (l <= bl && br <= r) {
    Shift(v, val);
    return;
  }
  int m = (bl + br) / 2;
  Touch(v);
  Add(bl, m, l, r, 2 * v, val);
  Add(m + 1, br, l, r, 2 * v + 1, val);
  drz[v] = Merge(drz[2 * v], drz[2 * v + 1]);
}



