/**
 * Description: 1D range update and query, $SZ=2^p$.
 * Source: USACO Counting Haybales
 * Verification: SPOJ Horrible
 */

template<class T, int SZ> struct LazySeg { 
	T mn[2*SZ], mx[2*SZ], lazy[2*SZ]; 
	LazySeg() { F0R(i,2*SZ) mn[i] = mx[i] = lazy[i] = 0; }
	void push(int ind, int L, int R) { /// modify values for current node
		if (L != R) F0R(i,2) lazy[2*ind+i] += lazy[ind]; /// prop to children
		mn[ind] += lazy[ind]; mx[ind] += lazy[ind];
		lazy[ind] = 0; 
	} // recalc values for current node
	void pull(int ind) { 
		mn[ind] = min(mn[2*ind],mn[2*ind+1]); 
		mx[ind] = max(mx[2*ind],mx[2*ind+1]); 
	}
	void build(int ind = 1, int L = 0, int R = SZ-1) {
		lazy[ind] = 0;
		if (L == R) {
			mn[ind] = mx[ind] = stor[L];
			return;
		}
		int M = (L+R)/2;
		build(2*ind,L,M); build(2*ind+1,M+1,R);
		pull(ind);
	}
	void upd(int lo,int hi,T inc,int ind=1,int L=0, int R=SZ-1) {
		push(ind,L,R); if (hi < L || R < lo) return;
		if (lo <= L && R <= hi) { 
			lazy[ind] = inc; push(ind,L,R); return; }
		int M = (L+R)/2; upd(lo,hi,inc,2*ind,L,M); 
		upd(lo,hi,inc,2*ind+1,M+1,R); pull(ind);
	}
	T qmax(int lo, int hi, int ind=1, int L=0, int R = SZ-1) {
		push(ind,L,R); if (lo > R || L > hi) return -MOD;
		if (lo <= L && R <= hi) return mx[ind];
		int M = (L+R)/2; 
		return max(qmax(lo,hi,2*ind,L,M),qmax(lo,hi,2*ind+1,M+1,R));
	}
	T qmin(int lo, int hi, int ind=1, int L=0, int R = SZ-1) {
		push(ind,L,R); if (lo > R || L > hi) return MOD;
		if (lo <= L && R <= hi) return mn[ind];
		int M = (L+R)/2; 
		return min(qmin(lo,hi,2*ind,L,M),qmin(lo,hi,2*ind+1,M+1,R));
	}
	int getMin(T x, int ind=1, int L=0, int R = SZ-1) { // max <= x
		push(ind,L,R); 
		if (mx[ind] <= x) return L; // OK
		if (L == R) return MOD;
		int M = (L+R)/2;
		int t = getMin(x,2*ind+1,M+1,R); if (t > M+1) return t;
		int u = getMin(x,2*ind,L,M); return u == MOD ? t : u;
	}
};

