  vector<int> h(n + 1);
  for (int i = 0; i < n; ++i) {
    if (s[i] == '1') {
      h[i + 1] = h[i] - 1;
    } else {
      h[i + 1] = h[i] + 1;
    }
  }
  int res = n;
  for (int t : {0, 1}) {
    range_add<int> ra(h);
    int mn = ra.min(0, n + 1);
    for (int i = 0; i < n; ++i) {
      if (s[i] != '?') continue;
      if (ra.min(i + 1, n + 1) - 2 >= mn - t) {
        ra.add(i + 1, n + 1, -2);
      }
    }
    int mx = ra.max(0, n + 1);
    res = min(res, mx - (mn - t));
  }
  cout << res << '\n';
}

