const int N = 1e6 + 100;
int pref[N],v[N],k[N],K[N],suf_k[N];


inline int min_max(int n,int m){

	for(int i = 0; i<=n; ++i){
		k[i] = (pref[i] + v[i] - m) / 2;
	}
	suf_k[n] = k[n];

	for(int i = n-1 ;i >= 0 ; --i){
		suf_k[i] = min(suf_k[i+1],k[i]);
	}


	// Kz is the number of positions that will be -1 in [1..z].
	// kz is the number of positions that will be -1 in [1..z] only taking m into consideration.
	// Kz = min( k z..n, K[z-1] + v[z] - v[z-1], v[z])
	// ans = max (pref[z] + v[z] - 2*K[z])

	// m -> (m-2)  ---> k'z <= k[z] + 1  ----> K'z <= K[z] + 1 ----> ans' >= ans - 2 
	// difference would be same or increase 
	int ans = 0;
	for(int i = 0; i<=n; ++i){
		K[i] = min(suf_k[i],v[i]);
		if ( i > 0){
			K[i] = min(K[i-1] + v[i] - v[i-1],K[i]);
		}

		assert(pref[i] + v[i] - 2*K[i] >= m);
		ans = max(ans, pref[i] + v[i] - 2*K[i]);
	}
	return ans;
}

