	int n = s.size();
	int L = 0, R = n + 3;
	int mid;
	int lz, rz, lf, rf;
	while(L + 1 < R){
		mid = (L + R) >> 1;
		lz = 0, rz = mid - (mid & 1);
		lf = 1, rf = mid - (1 - (mid & 1));

		bool flz = true, flf = true;
		for(auto &c : s){
			if(c == '0'){
				lz --; rz--;
				lf --; rf--;
			}
			if(c == '1'){
				lz ++;
				rz ++;
				lf ++; rf++;
			}
			if(c == '?'){
				lz --;
				rz ++;
				lf --;
				rf ++;
			}
			swap(lz, lf); swap(rz, rf); swap(flz, flf);
			lz = max(lz, 0); lf = max(lf, 1);
			rz = min(rz, mid - (mid & 1));
			rf = min(rf, mid - (1 - (mid & 1)));
			if(lz > rz) flz = false;
			if(lf > rf) flf = false;
		}
		if(flz || flf) R = mid;
