int f(int M, string S){
    int N = SZ(S);
    vec v(N + 1, 0);
    int now = 0, m = 0;
    IREP(i, N){
        if(S[i] == '1') now++;
        else now--;
        Min(m, now);
        v[i] = now - m;
    }

    m = 0, now = 0;
    REP(i, N){
        if(S[i] == '1') now++;
        else if(S[i] == '0') now--;
        else{
            if(now + 1 + v[i + 1] <= M) now++;
            else now--;
        }
        Min(m, now);
    }

    return m;
}

signed main(){

    string S; cin >> S;
    int N = SZ(S);

    int Z = 0, now = 0;
    REP(i, N){
        if(S[i] == '1') now++;
        else now--;
        Max(Z, now);
    }

    int ans = min(Z - f(Z, S), Z + 1 - f(Z + 1, S));
    Out(ans);

    return 0;
}

