int n;
char s[maxn + 5];
int l0[maxn + 5], r0[maxn + 5], l1[maxn + 5], r1[maxn + 5];
std::set<int> S;

int pre(int p) {
	auto it = S.lower_bound(p);
	if (it == S.begin()) return 0;
	return *--it;
}

int nxt(int p) {
	auto it = S.upper_bound(p);
	if (it == S.end()) return 0;
	return *it;
}

int c[maxn + 5];

void Add(int p, int v) {
	for (int i = p; i <= maxn; i += i & -i)
		c[i] += v;
}

int query(int p) {
	int res = 0;
	for (int i = p; i; i ^= i & -i)
		res += c[i];
	return res;
}

int query(int l, int r) {
	if (l && l <= r) return query(r) - query(l - 1);
	else return 0;
}

