	for (int i = 1; i <= n; ++i)
		if (s[i] == '?') S.insert(i);
		else if (s[i] == '1') Add(i, 1);
		else Add(i, -1);

	int s0 = 0, s1 = 0;
	for (int i = 1; i <= n; ++i) {
		if (s[i] == '0') { ++s0; if (s1) --s1; }
		else if (s[i] == '1') { ++s1; if (s0) --s0; }
		else l0[i] = s0, l1[i] = s1, s0 = s1 = 0;
	}

	s0 = 0, s1 = 0;
	for (int i = n; i; --i) {
		if (s[i] == '0') { ++s0; if (s1) --s1; }
		else if (s[i] == '1') { ++s1; if (s0) --s0; }
		else r0[i] = s0, r1[i] = s1, s0 = s1 = 0;
	}

	#define Push(i) que.push(Pair(std::max(l0[i] + r0[i], l1[i] + r1[i]), i))
	std::priority_queue<Pair> que;
	for (int i = 1; i <= n; ++i)
		if (s[i] == '?' && (s[i - 1] != '?' || s[i + 1] != '?'))
			Push(i);

	while (!que.empty()) {
		int u = que.top().second, tmp = que.top().first; que.pop();
		if (s[u] != '?') continue;
		if (l0[u] + r0[u] > l1[u] + r1[u]) s[u] = '1', Add(u, 1);
		else if (l0[u] + r0[u] < l1[u] + r1[u]) s[u] = '0', Add(u, -1);
		else if (tmp) que.push(Pair(0, u));
		else s[u] = '1', Add(u, 1);
		int l = pre(u), r = nxt(u);
		chkmax(r0[l], -query(l, u) + r0[u]);
		chkmax(r1[l], query(l, u) + r1[u]), Push(l);
		chkmax(l0[r], -query(u, r) + l0[u]);
		chkmax(l1[r], query(u, r) + l1[u]), Push(r);
		S.erase(u);
	}

	int res = 0; s0 = s1 = 0;
	for (int i = 1; i <= n; ++i) {
		if (s[i] == '0') { chkmax(res, ++s0); if (s1) --s1; }
		else if (s[i] == '1') { chkmax(res, ++s1); if (s0) --s0; }
	}

	printf("%d\n", res);
