seg operator +(seg x,seg y){
	seg z;
	z.mi=min(x.mi,y.mi);
	z.mx=max(x.mx,y.mx);
	if(x.mx==z.mx) z.mxs=x.mxs; else z.mxs=y.mxs;
	return z;
}
int tag[1000005];
void pushup(int x){
	tr[x]=tr[x+x]+tr[x+x+1];
}
void upd(int x,int y){
	tr[x].mx+=y;
	tr[x].mi+=y;
	tag[x]+=y;
}
void pushdo(int x){
	if(tag[x]){
		upd(x+x,tag[x]);
		upd(x+x+1,tag[x]);
		tag[x]=0;
	}
}
void build(int x,int l,int r){
	if(l==r){
		tr[x]=(seg){sa[l],sb[l],l};
		return;
	}
	int mid=(l+r)/2;
	build(x+x,l,mid);
	build(x+x+1,mid+1,r);
	pushup(x);
}
void update(int x,int l,int r,int ql,int qr,int c){
	if(ql<=l&&r<=qr){
		upd(x,c);return;
	}
	int mid=(l+r)/2;pushdo(x);
	if(ql<=mid)update(x+x,l,mid,ql,qr,c);
	if(qr>mid)update(x+x+1,mid+1,r,ql,qr,c);
	pushup(x); 
}
seg query(int x,int l,int r,int ql,int qr){
	if(ql<=l&&r<=qr){
		return tr[x];
	}
	int mid=(l+r)/2;pushdo(x);
	if(qr<=mid)return query(x+x,l,mid,ql,qr);
	if(ql>mid)return query(x+x+1,mid+1,r,ql,qr);
	return query(x+x,l,mid,ql,qr)+query(x+x+1,mid+1,r,ql,qr);
}
