int n, mi[N], sum[N];
char s[N];
int solve(int x) {
	//前缀和最小值不少于x时, 前缀和最大值的最小值
	int tot = 0, now = 0, mx = 0;
	REP(i,1,n) {
		if (s[i]=='?') {
			if (mi[i]-tot-2>=x) --now,tot+=2;
			else ++now;
		}
		else if (s[i]=='0') --now;
		else ++now;
		mx = max(mx, now);
	}
	return mx;
}
