	int _min = 0;
	int pr = 0;
	int rez = 0;
	for (int i = 0; i < le(v); i++) {
		pr += v[i];
		rez = max(rez, pr - _min);
		_min = min(_min, pr);
	}
	return rez;
}
int detec(vector<int> v, int S) {
	int _min = 0;
	int pr = 0;
	int check = 0;
	for (int i = 0; i < le(v); i++) {
		pr += v[i];
		if (pr - _min == S) {
			check |= (1 << (i & 1));
		}
		_min = min(_min, pr);
	}
	return check;
}
