int solve(int x, string s)
{
    vector<int> A(s.size());
    for (int i = 0; i < s.size(); i++)
    {
        if (i) A[i] = A[i - 1];
        if (s[i] == '0') A[i]++;
        else A[i]--;
    }
    vector<int> sufmax(s.size());
    for (int i = s.size() - 1; i >= 0; i--)
    {
        if (i + 1 < s.size()) sufmax[i] = sufmax[i + 1];
        else sufmax[i] = -1000000;
        sufmax[i] = max(sufmax[i], A[i]);
    }
    vector<int> will_go_down(s.size() + 1);
    for (int i = 0; i < s.size(); i++)
    {
        will_go_down[i] = max(0, sufmax[i] - (i > 0 ? A[i - 1] : 0));
    }
    /*for (int i = 0; i < s.size() + 1; i++)
    {
        cout << will_go_down[i] << " ";
    }
    cout << endl << endl;
    cout << x << endl;
    cout << will_go_down[0] << endl;*/
    assert(will_go_down[0] <= x);
    int c = 0, mx = 0, mn = 0;
    for (int i = 0; i < s.size(); i++)
    {
        if (s[i] == '1') c++;
        else if (s[i] == '0') c--;
        else
        {
            int D = -c + will_go_down[i + 1] + 1;
            if (D <= x) c--;
            else c++;
        }
        mx = max(mx, c);
        mn = min(mn, c);
    }
    //cout << endl;
    //cout << mn << " " << mx << endl;
    assert(-mn <= x);
    return mx;
}

