int solve(){
	int f, l, r, lx, ly, rx, ry;
	f = 0, l = 0, r = 0;
	lx = 0, ly = 0;
	rx = 0, ry = 0;
	for (int i = 1; i <= n; i++){
		if (s[i] == '0'){
			l--; r--;
			if (l < 0) l += 2;
			lx = max(0, lx - 1);
			ly = ly + 1;
			rx = max(0, rx - 1);
			ry = ry + 1;
			if (r < 0) l = r = rx, f = rx + ry;
		}
		if (s[i] == '1'){
			l++, r++;
			if (r > f) r -= 2;
			lx = lx + 1;
			ly = max(0, ly - 1);
			rx = rx + 1;
			ry = max(0, ry - 1);
			if (l > f) l = r = lx, f = lx + ly;
		}
		if (s[i] == '?'){
			lx = max(0, lx - 1);
			ly = ly + 1;
			rx = rx + 1;
			ry = max(0, ry - 1);
			l--; if (l < 0) l += 2;
			r++; if (r > f) r -= 2;
		}
		if (l == lx) ly = min(ly, f - l);
		if (f - r == ry) rx = min(rx, r);
	}
	return f;
}
