	void update(int a,int b,int x,int k=0,int l=0,int r=-1)//[a,b)
	{
		if(r<0)r=n;
		if(b<=l||r<=a)return;
		else if(a<=l&&r<=b)
		{
			lazy[k]+=x;
		}
		else
		{
			update(a,b,x,2*k+1,l,(l+r)/2);
			update(a,b,x,2*k+2,(l+r)/2,r);
			dat[k].first=max(dat[2*k+1].first+lazy[2*k+1],dat[2*k+2].first+lazy[2*k+2]);
			dat[k].second=max(dat[2*k+1].second+lazy[2*k+1],dat[2*k+2].second+lazy[2*k+2]);
		}
	}
	pair<int,int>query(int a,int b,int k=0,int l=0,int r=-1)//[a,b)
	{
		if(r<0)r=n;
		if(b<=l||r<=a)return make_pair(0,0);
		else if(a<=l&&r<=b)
		{
			return make_pair(dat[k].first+lazy[k],dat[k].second+lazy[k]);
		}
		else
		{
			pair<int,int>A=query(a,b,2*k+1,l,(l+r)/2),B=query(a,b,2*k+2,(l+r)/2,r);
			A.first=max(A.first,B.first)+lazy[k];
			A.second=min(A.second,B.second)+lazy[k];
			return A;
		}
	}
};
