	//lazysegtree<pair<int,int> >P(S.size()+1);
	stack<pair<int,int> >m0,m1;
	m0.push(make_pair(0,0));
	m1.push(make_pair(0,0));
	for(int i=0;i<S.size();i++)
	{
		if(S[i]=='0')
		{
			now1--;
			now0--;
			//P.update(i+1,S.size()+1,-1);
		}
		else if(S[i]=='1')
		{
			now1++;
			now0++;
			//P.update(i+1,S.size()+1,1);
		}
		else
		{
			now1++;
			now0--;
			Q.push(i+1);
		}
		if(now1-m1.top().first==-lim)
		{
			int id=m1.top().second;
			vector<int>del;
			while(!Q.empty()&&Q.top()>id)
			{
				int j=Q.top();Q.pop();
				//P.update(j,S.size()+1,1);
				now0+=2;
				del.push_back(j);
			}
			reverse(del.begin(),del.end());
			vector<pair<int,int> >dm;
			while(m0.top().second>id)
			{
				dm.push_back(m0.top());
				m0.pop();
			}
			int k=0;
			for(int j=dm.size();j--;)
			{
				while(k<del.size()&&del[k]<=dm[j].second)k++;
				int X=dm[j].first+k*2;
				if(m0.top().first>X)m0.push(make_pair(X,dm[j].second));
			}
		}
		if(now0-m0.top().first==lim)
		{
			int id=m0.top().second;
			vector<int>del;
			while(!Q.empty()&&Q.top()>id)
			{
				int j=Q.top();Q.pop();
				//P.update(j,S.size()+1,-1);
				now1-=2;
				del.push_back(j);
			}
			reverse(del.begin(),del.end());
			vector<pair<int,int> >dm;
			while(m1.top().second>id)
			{
				dm.push_back(m1.top());
				m1.pop();
			}
			int k=0;
			for(int j=dm.size();j--;)
			{
				while(k<del.size()&&del[k]<=dm[j].second)k++;
				int X=dm[j].first-k*2;
				if(m1.top().first<X)m1.push(make_pair(X,dm[j].second));
			}
		}
		if(now1-m1.top().first<-lim||now0-m0.top().first>lim)return false;
		A0[i+1]=now0;
		if(m0.top().first>now0)m0.push(make_pair(now0,i+1));
		A1[i+1]=now1;
		if(m1.top().first<now1)m1.push(make_pair(now1,i+1));
	}
	return true;
}
