int main(void){
	string s;
	cin >> s;

	while(!s.empty()){
		if (s.back() == '?') s.pop_back();
		else
			break;
	}

	ll n = s.size();

	if(n == 0){
		co(1);
		return 0;
	}

	ll l = 0, r = n;
	while(r - l > 1){
		ll m = (l + r) / 2;
		ll mi = 0, ma = m;
		repr(i, n){
			if (s[i] == '0'){
				++mi;
				if (ma < m) ++ma;
			}
			else if(s[i] == '1'){
				--ma;
				if (mi > 0) --mi;
			}else{
				if (mi > 0) --mi;
				else
					++mi;
				if (ma < m) ++ma;
				else
					--ma;
				if (mi > ma) swap(mi, ma);
			}

			if (mi > ma) break;
		}

		if (mi <= ma) r = m;
		else
			l = m;
	}
	co(r);

	return 0;
}

