#define ls p<<1
#define rs p<<1|1
void update(int p)
{
	a[p].mx = max(a[ls].mx, a[rs].mx);
	a[p].mn = min(a[ls].mn, a[rs].mn);
}
void pushdown(int p)
{
	if (a[p].lz)
	{
		a[ls].mx += a[p].lz;
		a[ls].mn += a[p].lz;
		a[ls].lz += a[p].lz;
		a[rs].mx += a[p].lz;
		a[rs].mn += a[p].lz;
		a[rs].lz += a[p].lz;
		a[p].lz = 0;
	}
}
void add(int x, int y, ll v, int l, int r, int p)
{
	if (x<=l&&r<=y)
	{
		a[p].mx += v;
		a[p].mn += v;
		a[p].lz += v;
		return;
	}
	pushdown(p);
	int m = l+r>>1;
	if (x<=m) add(x, y, v, l, m, ls);
	if (m<y) add(x, y, v, m+1, r, rs);
	update(p);
}
int query(int x, int y, int l, int r, int p)
{
	if (x<=l&&r<=y) return a[p].mx;
	pushdown(p);
	int m = l+r>>1;
	if (x<=m&&m<y) return max(query(x, y, l, m, ls), query(x, y, m+1, r, rs));
	else if (x<=m) return query(x, y, l, m, ls);
	else return query(x, y, m+1, r, rs);
}
