struct SegTree {
	struct Node {
		int push;
		int minval;
		int maxval;
		int wheremin;

		Node() : push(0), minval(0), maxval(0), wheremin(0) {};

		Node Merge(const Node &rhs) const {
			Node ans;
			ans.minval = min(minval, rhs.minval);
			ans.maxval = max(maxval, rhs.maxval);
			ans.wheremin = 1e9;
			if (ans.minval == minval) {
				ans.wheremin = min(ans.wheremin, wheremin);
			} else {
				ans.wheremin = min(ans.wheremin, rhs.wheremin);
			}
			return ans;
		}
	};

	vector<Node> nodes;
	int base;

	SegTree(int n) : base(1) {
		while (base < n + 1) { base *= 2; }
		nodes.resize(base * 2);
		for (int i = 0; i < base; ++i) {
			nodes[base+i].wheremin = i;
		}
		for (int i = base-1; i >= 0; --i) {
			nodes[i] = nodes[i*2].Merge(nodes[i*2+1]);
		}
	}

	int lv, rv, valv;

	void Touch(int v) {
		if (v < base) {
			for (int s : {v*2, v*2+1}) {
				nodes[s].minval += nodes[v].push;
				nodes[s].maxval += nodes[v].push;
				nodes[s].push += nodes[v].push;
			}
		}
		nodes[v].push = 0;
	}

	void AddValRec(int lbase, int rbase, int v) {
		if (lbase >= rv || rbase <= lv) { return; }
		Touch(v);
		if (lv <= lbase && rbase <= rv) {
			nodes[v].minval += valv;
			nodes[v].maxval += valv;
			nodes[v].push += valv;
			return;
		}

		const int mid = (lbase + rbase) / 2;
		AddValRec(lbase, mid, v*2);
		AddValRec(mid, rbase, v*2+1);
		nodes[v] = nodes[v*2].Merge(nodes[v*2+1]);
	}

	void AddVal(int L, int R, int val) {
		lv = L; rv = R; valv = val;
		return AddValRec(0, base, 1);
	}
};

int Kadane(vi &v) {
	int best = 0, cur = 0;
	for (int x : v) {
		cur += x;
		if (cur < 0) { cur = 0; }
		if (cur > best) { best = cur; }
	}
	return best;
}

