int pre[1000005];
const int N=1e6+5;
int tr[4*N],lazy[4*N];
void add(int seg, int ll, int rr, int l, int r, int val) {
	if(ll>r||l>rr)
		return;
	if(l<=ll&&rr<=r) {
		tr[seg]+=val;
		lazy[seg]+=val;
		return;
	}
	if(lazy[seg]) {
		tr[seg<<1]+=lazy[seg];
		tr[seg<<1|1]+=lazy[seg];
		lazy[seg<<1]+=lazy[seg];
		lazy[seg<<1|1]+=lazy[seg];
		lazy[seg]=0;
	}
	add(seg<<1,ll,(ll+rr)/2,l,r,val);
	add(seg<<1|1,1+(ll+rr)/2,rr,l,r,val);
	tr[seg]=max(tr[seg<<1],tr[seg<<1|1]);
}
int query(int seg, int ll, int rr, int p) {
	if(ll==p&&rr==p) {
		return tr[seg];
	}
	if((ll+rr)/2>=p)
		return query(seg<<1,ll,(ll+rr)/2,p);
	else
		return query(seg<<1|1,1+(ll+rr)/2,rr,p);
}
void solve() {
	string s;
