	int n=sz(s);
	s='0'+s;
	set<int> q;
	vi lami;
	lami.pb(0);
	fr(i,1,n) {
		if(s[i]=='?') {
			q.insert(i);
			s[i]='0';
		}
		pre[i]=pre[i-1]+2*s[i]-'0'-'1';
		if(pre[i]<pre[lami.back()])
			lami.pb(i);
	}
	fr(i,0,n)
		add(1,0,n,i,i,pre[i]);
	trace(1);
	if(sz(lami)==1) {
		cout<<*max_element(pre,pre+n+1)<<endl;
		return;
	}
	set<int> q2=q;
	vi lami2=lami;
	int ans=(*max_element(pre,pre+n+1))-(*min_element(pre, pre+n+1));
	for(int i=-n-1; i<=0; i+=2) {
		while(query(1,0,n,lami[sz(lami)-2])<i)
			lami.pop_back();
		if(query(1,0,n,lami.back())<i) {
			auto it=q2.upper_bound(lami.back());
			if(it==q2.begin()) {
				break;
			} else {
				it--;
				add(1,0,n,*it,n,+2);
				q2.erase(it);
			}
		}
		ans=min(ans,abs(i-tr[1]));
	}
	swap(lami,lami2);
	swap(q2,q);
	memset(tr,0,sizeof(tr));
	memset(lazy,0,sizeof(lazy));
	fr(i,0,n)
		add(1,0,n,i,i,pre[i]);
	for(int i=-n; i<=0; i+=2) {
		while(query(1,0,n,lami[sz(lami)-2])<i)
			lami.pop_back();
		if(query(1,0,n,lami.back())<i) {
