    // return 0;

    //even
    int low = -delta;
    int high = 0;
    if (low & 1) low++;
    if (high & 1) high--;
    while (high - low > 2) {
        int mid = (low + high) / 2;
        if (mid & 1) mid++;
        int val = eval(mid, delta);
        if (val == 0) return 1;
        if (val == 1) high = mid;
        else low = mid;
    }
    if (eval(low, delta) == 0 ||  eval(high, delta) == 0) return 1;

    //odd
    low = -delta;
    high = 0;
    if (low % 2 == 0) low++;
    if (high % 2 == 0) high--;
    while (high - low > 2) {
        int mid = (low + high) / 2;
        if (mid % 2 == 0) mid++;
        int val = eval(mid, delta);
        if (val == 0) return 1;
        if (val == 1) high = mid;
        else low = mid;
    }
    if (eval(low, delta) == 0 ||  eval(high, delta) == 0) return 1;
    return 0;
}

