            vp.emplace_back(acc, i + 1);
            vpinv.emplace_back(-acc, -i - 1);
        }
    }
    RangeAddRangeMin<pint> sst(vp, pint(1e9, -1));
    RangeAddRangeMin<pint> sstinv(vpinv, pint(1e9, -1));

