struct BIT{
	int size;
	vector<llint> bit;
	BIT(){size = 0;}
	BIT(int s){
		size = s;
		bit.resize(size+1);
		init();
	}
	void init(){
		for(int i = 1; i <= size; i++) bit[i] = 0;
	}
	llint query(int i){
		llint ret = 0;
		while(i > 0){
			ret += bit[i];
			i -= i&(-i);
		}
		return ret;
	}
	void add(int i, llint x){
		while(i <= size){
			bit[i] += x;
			i += i&(-i);
		}
	}
};

string s;
BIT bit(1000005);

void update(llint p, llint x)
{
	llint v = bit.query(p), d = x - v;
	bit.add(p, d), bit.add(p+1, -d);
}

llint get(llint l, llint r)
{
	llint ub = r+1, lb = l-1, mid;
	while(ub-lb>1){
		mid = (ub+lb)/2;
		llint res = bit.query(mid);
		if(res > 0){
			if(res > inf/2){
				if(bit.query(mid+1) > 0 || bit.query(mid-1) > 0) lb = mid;
				else ub = mid;
			}
			else lb = mid;
		}
		else ub = mid;
	}
	return lb;
}

