	update(1000002, 0);

	llint l = 1000002, r = 1000002, k = 1000002;
	for(int i = 1; i <= n; i++){
		if(s[i] == '0'){
			llint res = get(l, r);
			//cout << res << endl;
			if(res >= l) bit.add(l, -1), bit.add(res+1, 1);
			l--;
			update(l, inf);
		}
		if(s[i] == '1'){
			bit.add(l, 1), bit.add(r+1, -1);
			if(l < r) l++;
			llint x = min(bit.query(l-1), bit.query(l));
			update(l, x);
			update(l-1, inf);
		}
		if(s[i] == '?'){
			if(l == k){
				llint x = min(bit.query(k), bit.query(k+1))+1;
				llint res = get(l, r);
				//cout << "!" << res << endl;
				if(res >= l) bit.add(l, -1), bit.add(res+1, 1);
				l--; k--;
				update(k, x);
			}
			else{
				llint x = bit.query(k+1)+1, y = bit.query(k)+1;
				llint res = get(l, r);
				if(res >= l) bit.add(l, -1), bit.add(res+1, 1);
				l--; k-=2;
				update(k, y), update(k+1, x);
			}
		}
		k = max(l, k);
		//for(int i = l; i <= r; i++) cout << bit.query(i) << " "; cout << endl;
	}

	llint ans = inf;
	for(int i = l; i <= r; i++){
		ans = min(ans, bit.query(i)+(i-l));
	}
	cout << ans << endl;

	return 0;
}

