			int box = dp[oddfst];
			if (box % 2 == 0)box++;
			if (box <= oddeq) {
				dp[box] = max(box, dp[box]);
				odd.insert(box);
			}
		}

		if (eveneq != 0) {
			for (int j = -0; j <= 0; j += 2) {
				if (eveneq + j >= evenfst)even.insert(eveneq + j);
			}
		}

		if (evenfst != MOD) {
			even.insert(evenfst);
			for (int j = 0; j <= 0; j += 2) {
				even.insert(evenfst + j);
			}
			int box = dp[evenfst];
			if (box % 2 == 1)box++;
			if (box <= eveneq) {
				dp[box] = max(dp[box], box);
				even.insert(box);
			}
		}
	}
	int ans = MOD;
	for (auto i : odd)ans = min(ans, dp[i]);
	for (auto i : even)ans = min(ans, dp[i]);
	cout << ans << endl;
	return 0;
}

