    cin >> A >> B >> C >> D;

    INIT(dp, 0);
    dp[A][B] = 1;

    for_(i,A+1,C+1) modAdd(dp[i][B], dp[i - 1][B] * B);
    for_(j,B+1,D+1) modAdd(dp[A][j], dp[A][j - 1] * A);

    for_(i,A+1,C+1) for_(j,B+1,D+1) {
        lint x = (dp[i][j - 1] * i) % MOD;
        lint y = (dp[i - 1][j] * j) % MOD;
        lint z = (dp[i - 1][j - 1] * (i - 1) * (j - 1)) % MOD;
        lint add = (x + y - z + MOD) % MOD;
        modAdd(dp[i][j], add);
    }

    cout << dp[C][D] << endl;
}

