					if (st.minx != st.maxx) {
						tmp.push_back({st.len, st.minx + 1, st.maxx - 1});
					}
					tmp.push_back({st.len + 1, st.len + 1, st.len + 1});
				}
			}
		}
		sort(all(tmp), [](const State& s, const State& t) {
			return s.len < t.len;
		});
		a.clear();
		for (auto s : tmp) {
			while (s.minx <= s.maxx) {
				bool cov = false;
				for (auto t : a) {
					if (isCovered(t, s.minx, s.len - s.minx)) {
						cov = true;
						break;
					}
				}
				if (cov) {
					s.minx += 2;
				} else {
					break;
				}
			}
			while (s.minx <= s.maxx) {
				bool cov = false;
				for (auto t : a) {
					if (isCovered(t, s.maxx, s.len - s.maxx)) {
						cov = true;
						break;
					}
				}
				if (cov) {
					s.maxx -= 2;
				} else {
					break;
				}
			}
			if (s.minx <= s.maxx) {
				a.push_back(s);
			}
		}
		// cerr << c;
		// if (a.size() > 10) {
		// 	cerr << "\n";
		// 	return 0;
		// }
	}
	int ans = 1e8;
	for (auto s : a) {
		ans = min(ans, s.len);
	}
	cout << ans << "\n";

	return 0;
}

