string S;

bool check(int d) {
  int low = 0;
  int high = d;

  for (auto &c : S) {
    if (c == '?') {
      if (high == 0) {
        low = 1;
        high = 1;
      } else if (low == d) {
        low = d - 1;
        high = d - 1;
      } else {
        low = max(low - 1, 0ll);
        high = min(high + 1, d);
      }
    } else if (c == '0') {
      if (high == 0)
        return false;
      low = max(low - 1, 0ll);
      high--;
    } else if (c == '1') {
      if (low == d)
        return false;
      low++;
      high = min(high + 1, d);
    }
    if (low > high) {
      return false;
    }
    // cerr << low << " " << high << endl;
  }
  return true;
}

