const int INF = 1e9;
struct MUStructMax{
    struct Monoid{
        using value_t=pair<int,int>;
        static constexpr value_t E(){return make_pair(-INF,-INF);}
        static value_t op(value_t lhs,value_t rhs){ return max(lhs,rhs);}
    };
    struct Update{
        using update_t = int;
        static update_t op(update_t lhs,update_t rhs){ return lhs+rhs;}
    };
    static Monoid::value_t evaluate(Monoid::value_t v,Update::update_t u){ return make_pair(v.first+u,v.second);}
};

struct MUStructMin{
    struct Monoid{
        using value_t=pair<int,int>;
        static constexpr value_t E(){return make_pair(INF,INF);}
        static value_t op(value_t lhs,value_t rhs){ return min(lhs,rhs);}
    };
    struct Update{
        using update_t = int;
        static update_t op(update_t lhs,update_t rhs){ return lhs+rhs;}
    };
    static Monoid::value_t evaluate(Monoid::value_t v,Update::update_t u){ return make_pair(v.first+u,v.second);};
};

const int start = -1e6-1;
int main(){
    string s;
    cin>>s;
    int n = s.size();
    LazySegmentTree<MUStructMax> maxSeg(n);
    LazySegmentTree<MUStructMin> minSeg(n);
    for(int i=0;i<n;i++){
        maxSeg.update(i,{0,i});
        minSeg.update(i,{0,i});
    }
    for(int i=0;i<n;i++){
        if(s[i]=='1'){
            maxSeg.apply(i,n,1);
            minSeg.apply(i,n,1);
        }
        else{
            maxSeg.apply(i,n,-1);
            minSeg.apply(i,n,-1);
        }
    }

    set<int> q_set;
    for(int i=0;i<n;i++){
        if(s[i]=='?') q_set.insert(i);
    }
    int pre = -1;
    int res = INF;
    for(int lb=start;;lb++){
        auto ret = minSeg.query(0,n);
        // cerr<<"$$"<<lb<<endl;
        // cerr<<"$"<<endl;
        // for(int i=0;i<n;i++){
        //     auto ret = maxSeg.query(i,i+1);
        //     cerr<<ret.first<<" ";
        // }
        // cerr<<endl;
        if(ret.first<lb){
            int id = ret.second;
            auto it = q_set.upper_bound(id);
            if(it==q_set.begin()){
                break;
            }
            it--;
            int pos = *it;
            minSeg.apply(pos,n,2);
            maxSeg.apply(pos,n,2);
            q_set.erase(pos);
            if(pre!=-1){
                auto ret = minSeg.query(pre,n);
                if(lb+2<=ret.first){
                    minSeg.apply(pre,n,-2);
                    maxSeg.apply(pre,n,-2);
                    q_set.insert(pre);
                }
            }
            pre=pos;
        }
        // cerr<<"#"<<endl;
        // for(int i=0;i<n;i++){
        //     auto ret = maxSeg.query(i,i+1);
        //     cerr<<ret.first<<" ";
        // }
        // cerr<<endl;
        auto retmin = minSeg.query(0,n);
        auto retmax = maxSeg.query(0,n);
        assert(retmin.first>=lb);
        res = min(res,max(retmax.first,0)-min(retmin.first,0));
    }
    cout<<res<<endl;
    return 0;
}

