void solve() {
    RS(s);
    int n=LEN(s);
    int st=0;
    while(st<n&&s[st]=='?')st++;
    for(int i=st,j;i<n;i=j){
        if(s[i]=='?'){
            mark[SZ(AA)-1]++;
            j=i+1;
            continue;
        }
        int now=0;
        int mi=0,ma=0;
        for(j=i;j<n&&s[j]!='?';j++){
            if(s[j]=='0')now--;
            else now++;
            mi=min(mi,now);
            ma=max(ma,now);
        }
        AA.PB({mi,ma,now});
    }
    REPP(i,1,SZ(AA)){
        if(bb[i-1]+AA[i-1][2]-AA[i-1][0]-mark[i-1]+AA[i][0]>=0){
            bb[i]=max(bb[i],bb[i-1]+AA[i-1][2]-AA[i-1][0]-mark[i-1]+AA[i][0]);
        }
        else{
            if((bb[i-1]+AA[i-1][2]-AA[i-1][0]+mark[i-1]+AA[i][0])>=0){
                bb[i]=max(bb[i],(bb[i-1]+AA[i-1][2]-AA[i-1][0]+mark[i-1]+AA[i][0])%2);
            }
        }
    }
    for(int i=SZ(AA)-2;i>=0;i--){
        if(bb[i+1]-AA[i+1][0]-mark[i]+AA[i][0]>=0){
            bb[i]=max(bb[i],bb[i+1]-AA[i+1][0]-mark[i]+AA[i][0]);
        }
        else{
