                bb[i]=max(bb[i],(bb[i+1]-AA[i+1][0]+mark[i]+AA[i][0])%2);
            }
        }
    }
    int an=0;
    REP(i,SZ(AA)){
        an=max(an,bb[i]+AA[i][1]-AA[i][0]);
    }
    W(an);
}
