template<typename T>
struct StarrySky {
    int n, n_org;
    T e;
    vector<T> dat;
    vector<int> added;
    typedef function<T(T a, T b)> Func;
    Func f;

    StarrySky(){}
    StarrySky(int n_input, Func f_input, T e_input){
        initialize(n_input, f_input, e_input);
    }
    void initialize(int n_input, Func f_input, T e_input){
        n_org = n_input;
        f = f_input;
        e = e_input;
        n = 1;
        while(n < n_input) n <<= 1;
        dat.assign(2*n-1, e);
        added.assign(2*n-1, 0);
    }

    void build(vector<T>& A){
        for(int k=0; k<int(A.size()); k++) dat[k+n-1] = A[k];
        for(int k=n-2; k>=0; k--) dat[k] = f(dat[2*k+1], dat[2*k+2]);
    }

    void add_between(int a, int b, int x){
        add(a, b+1, x, 0, 0, n);
    }

    void add(int a, int b, int x, int k, int lb, int rb){
        if(b <= lb || rb <= a) return;
        if(a <= lb && rb <= b){
            added[k] += x;
        }else{
            int mb = (lb+rb)>>1;
            add(a, b, x, 2*k+1, lb, mb);
            add(a, b, x, 2*k+2, mb, rb);
            dat[k] = f(ad(dat[2*k+1], added[2*k+1]), ad(dat[2*k+2], added[2*k+2]));
        }
    }

    T between(int a, int b){
        return query(a, b+1, 0, 0, n);
    }

    T query(int a, int b, int k, int l, int r){
        if(r<=a || b<=l) return e;
        if(a<=l && r<=b) return ad(dat[k], added[k]);
        T vl = query(a, b, 2*k+1, l, (l+r)/2);
        T vr = query(a, b, 2*k+2, (l+r)/2, r);
        return ad(f(vl, vr), added[k]);
    }
};

