class Main {
  static int solve(char [] s, int minPrefix) {
    int sum = 0, maxPrefix = 0;
    TreeSet <Integer> index = new TreeSet <> ();
    for(int i = 0; i < s.length; i++) {
      if(s[i] == '1') {
        sum += 1;
      } else {
        sum -= 1;
        if(s[i] == '?') {
          index.add(i);
          s[i] = '0';
        }
      }
      while(sum < minPrefix) {
        if(index.isEmpty()) return Integer.MAX_VALUE;
        int optIndex = index.last();
        index.remove(optIndex);
        s[optIndex] = '1';
        sum += 2;
      }
    }
    sum = 0;
    for(int i = 0; i < s.length; i++) {
      if(s[i] == '1') {
        sum += 1;
      } else {
        sum -= 1;
      }
      maxPrefix = Math.max(maxPrefix, sum);
    }
    return maxPrefix - minPrefix;
  }
  public static void main(String [] args) {
    Reader in = new Reader();
    char [] s = in.next().toCharArray();
    int sum = 0;
    int start = 0;
    for(int i = 0; i < s.length; i++) {
      if(s[i] == '0') sum -= 1;
      else sum += 1;
      start = Math.min(start, sum);
    }
    System.out.println(Math.min(solve(s.clone(), start), solve(s.clone(), start - 1)));
  }
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		String s = sc.next();
		int ans = 0;
		for (int i = 0; i < s.length(); i++) {
			for (int j = i + 1; j <= s.length(); j++) {
				// より最大が見つかったら
				int ans1 = calcAns(s.substring(i, j));
				if (ans < ans1) {
					ans = ans1;
				}
			}
		}
		System.out.println(ans);
	}

	private static int calcAns(String s) {
		int count0 = 0;
		int count1 = 0;
		int countHatena = 0;
		for (char x : s.toCharArray()) {
			if ('0' == x)
				count0++;
			else if ('1' == x)
				count1++;
			else
				countHatena++;
		}
		int ans = 0;
		if (countHatena == 0) {
			ans = Math.abs(count1 - count0);
		} else if (count0 < count1) {
			if (countHatena >= count1 - count0) {
				count0 += (count1 - count0);
				countHatena = (count1 - count0) / 2;
				if (countHatena % 2 != 0) {
					ans = 1;
				}
			} else {
				count0 += countHatena;
				ans = Math.abs(count1 - count0);
			}
		} else if (count0 > count1) {
			if (countHatena >= count0 - count1) {
				count1 += (count0 - count1);
				countHatena = (count0 - count1) / 2;
				if (countHatena % 2 != 0) {
					ans = 1;
				}
			} else {
				count1 += countHatena;
				ans = Math.abs(count0 - count1);
			}
		} else {
			if (countHatena == 0 || countHatena % 2 != 0) {
				ans = 1;
			}
		}
		if (ans == 1)
			System.out.println(s);
		return ans;
	}
}

