namespace AtCoder {
    class Unbalanced {
        static bool can(string S, int H) {
            int from = 0, to = H;
            bool parityFlag = false;
            for (int i = 0; i < S.Length; i++) {
                if (from == to) {
                    parityFlag = true;
                }

                if (!parityFlag) {
                    if (S[i] == '0') {
                        if (from == H) {
                            return false;
                        }

                        from++;
                        to = Math.Min(to + 1, H);
                    } else if (S[i] == '1') {
                        if (to == 0) {
                            return false;
                        }

                        from = Math.Max(from - 1, 0);
                        to--;
                    } else {
                        from = Math.Max(from - 1, 0);
                        to = Math.Min(to + 1, H);
                    }
                } else {
                    if (S[i] == '0') {
                        if (from == H) {
                            return false;
                        }

                        from++;
                        to = (to == H ? to - 1 : to + 1);
                    } else if (S[i] == '1') {
                        if (to == 0) {
                            return false;
                        }
                        from = (from == 0 ? 1 : from - 1);
                        to--;
                    } else {
                        from = (from == 0 ? 1 : from - 1);
                        to = (to == H ? to - 1 : to + 1);
                        if (from > to) {
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        static void Main(string[] args) {
            string S = Console.ReadLine();
            int N = S.Length;

            int L = 0, R = N;

            while (R - L > 1) {
                int H = (L + R) / 2;
                if (can(S, H)) {
                    R = H;
                } else {
                    L = H;
                }
            }

            Console.WriteLine(R);
        }
    }
}

