        int[] min = new int[2];

        int[] odd = new int[2];
        int[] even = new int[2];

        for (int i = 0; i < S.Length; i++)
        {
            for (int j = 0; j < 2; j++)
            {
                if (S[i] == (char)('0' + j)) now[j]++;
                else now[j]--;
                min[j] = Math.Min(now[j], min[j]);
                int max = now[j] - min[j];

                if(i % 2 == 1) odd[j] = Math.Max(odd[j], max);
                else even[j] = Math.Max(even[j], max);
            }
        }

        int[] ans = new int[2];

        for (int j = 0; j < 2; j++)
        {
            if (odd[j] == even[j]) ans[j] = odd[j] + 1;
            else ans[j] = Math.Max(odd[j], even[j]);
        }

        Console.WriteLine(Math.Max(ans[0], ans[1]));
    }

