def bisect(ng, ok, judge):
    while abs(ng-ok) > 1:
        m = (ng+ok)//2
        if judge(m):
            ok = m
        else:
            ng = m
    return ok

def solve(S):
    d = {'0':-1,'1':1,'?':0}
    S = [d[c] for c in S]

    def judge(target_lo, target_hi):
        lo = 0
        hi = 0
        for s in S:
            if s == 0:
                lo -= 1
                hi += 1
            elif s == 1:
                lo += 1
                hi += 1
            else:
                lo -= 1
                hi -= 1
            hi = min(hi, target_hi-(target_hi+hi)%2)
            lo = max(lo, target_lo+(target_lo+lo)%2)
            if hi < lo:
                return False
        return True

    best = 10**6*2
    lo = -10**6
    hi = 10**6
    while True:
        hi = bisect(-1,10**6, lambda x: judge(lo, x))
        lo = bisect(1, -10**6, lambda x: judge(x, hi))
        if hi-lo >= best:
            break
        else:
            best = hi-lo
    hi += 1
    lo = bisect(1, -10**6, lambda x: judge(x, hi))

    best = min(best, hi-lo)
    return best

