def f(S, N, n):
    (L, U) = (n, n)

    for i in range(len(S)):
        #print(N, n, i, L, U)

        if S[i] == "0":
            U -= 1
            L -= 1
            if L < 0:
                L += 2
                if L > U:
                    return -1

        if S[i] == "1":
            U += 1
            L += 1
            if U > N:
                U -= 2
                if L > U:
                    return 1

        if S[i] == "?":
            U += 1
            L -= 1
            if U > N: 
                U -= 2
                if L > U:
                    return 1
            if L < 0: 
                L += 2
                if L > U:
                    return -1


    return 0

