    while lower <= upper:
        n = (lower + upper) // 2
        t = f(S, N, n)
        #print("{} = f(S, {}, {})".format(t, N, n))

        if lower < upper:
            if t == 1:
                upper = n
            if t == -1:
                lower = n + 1
            if t == 0:
                return True
        else:
            if t == 0:
                return True
            else:
                return False

