// [upper_limit, lower_limit), [lower, upper), binary step
#[derive(Debug, Clone)]
pub struct LimittedBinStepRange {
    lower: i64,
    upper: i64,
    lower_limit: i64,
    upper_limit: i64,
}

impl LimittedBinStepRange {
    pub fn new(lower: i64, upper: i64, lower_limit: i64, upper_limit: i64) -> LimittedBinStepRange {
        assert!(lower & 1 != upper & 1);
        LimittedBinStepRange {
            lower,
            upper,
            lower_limit,
            upper_limit,
        }
    }
    pub fn fix(&mut self) {
        if self.lower < self.lower_limit {
            self.lower += (self.lower_limit - self.lower + 1) / 2 * 2;
        }
        if self.upper > self.upper_limit {
            self.upper -= (self.upper - self.upper_limit + 1) / 2 * 2;
        }
    }
    pub fn add(&self, x: i64) -> LimittedBinStepRange {
        let mut res = self.clone();
        res.lower += x;
        res.upper += x;
        res.fix();
        res
    }
    pub fn unite(s: LimittedBinStepRange, t: LimittedBinStepRange) -> LimittedBinStepRange {
        assert!(s.lower_limit == t.lower_limit);
        assert!(s.upper_limit == t.upper_limit);
        let mut res = LimittedBinStepRange::new(
            min(s.lower, t.lower),
            max(s.upper, t.upper),
            s.lower_limit,
            t.upper_limit,
        );
        res.fix();
        res
    }
    pub fn is_empty(&self) -> bool {
        !(self.lower < self.upper)
    }
}

