use proconio::*;
use proconio::marker::Chars;

fn valid(s: &[char], p: i32, parity: i32) -> bool {
    let mut l = parity;
    let mut r = if p % 2 == 0 {
        p / 2 * 2 - parity
    } else {
        p / 2 * 2 + parity
    };
//    println!("query {} {}, s: {} {}", p, parity, l, r);
    for &c in s.iter() {
        match c {
            '0' => {
                l += 1;
                r += if r + 1 > p {
                    -1
                } else {
                    1
                };
            },
            '1' => {
                l -= if l == 0 {
                    -1
                } else {
                    1
                };
                r -= 1;
            },
            _ => {
                l -= if l == 0 {
                    -1
                } else {
                    1
                };
                r += if r + 1 > p {
                    -1
                } else {
                    1
                };
            },
        }
        if l > r {
            return false;
        }
    }
    true
}

fn run() {
    input! {
        s: Chars,
    }
    let mut ng = 0;
    let mut ok = 1_000_000;
    while ok - ng > 1 {
        let mid = (ok + ng) / 2;
        if valid(&s, mid, 0) || valid(&s, mid, 1) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    println!("{}", ok);
}

fn main() {
    run();
}

