        s: chars,
    }
    */
    let mut s = vec![];
    for _ in 0..1000000 {
        s.push('?');
    }

    let f = |upper_limit: i64| {
        let mut lower_limit = -((1i64 << 21) - 1);
        'b: for d in (0..21).rev() {
            let t = lower_limit + (1 << d);
            let mut range = LimittedBinStepRange::new(0, 1, t, upper_limit);
            //// eprintln!("range = {:?}", range);
            for &c in &s {
                if c == '0' {
                    range = range.add(1);
                }
                if c == '1' {
                    range = range.add(-1);
                }
                if c == '?' {
                    range = LimittedBinStepRange::unite(range.add_unsafe(1), range.add_unsafe(-1));
                }
                //// eprintln!("range = {:?}", range);
                if range.is_empty() {
                    continue 'b;
                }
            }
            //// eprintln!("t = {}, range = {:?}", t, range);
            if !range.is_empty() {
                lower_limit = t;
            }
        }
        //// eprintln!("upper_limit = {}, lower_limit = {}", upper_limit, lower_limit);
        upper_limit - lower_limit
    };

    let mut upper_limit_0 = 1;
    let mut upper_limit_3 = 1i64 << 21;
    let mut memo = BTreeMap::new();
    while upper_limit_3 - upper_limit_0 > 10 {
        let upper_limit_1 = (upper_limit_0 * 2 + upper_limit_3) / 3;
        let upper_limit_2 = (upper_limit_0 + upper_limit_3 * 2) / 3;
        let f_upper_limit_1 = *memo.entry(upper_limit_1).or_insert(f(upper_limit_1));
        let f_upper_limit_2 = *memo.entry(upper_limit_2).or_insert(f(upper_limit_2));
