                reader: reader,
                buf: vec![],
                pos: 0,
            }
        }
        pub fn update_buf(&mut self) {
            self.buf.clear();
            self.pos = 0;
            loop {
                let (len, complete) = {
                    let buf2 = self.reader.fill_buf().unwrap();
                    self.buf.extend_from_slice(buf2);
                    let len = buf2.len();
                    (len, buf2[len - 1] <= 0x20)
                };
                self.reader.consume(len);
                if complete {
                    break;
                }
            }
        }
        pub fn next<T: str::FromStr>(&mut self) -> Result<T, T::Err> {
            loop {
                let mut begin = self.pos;
                while begin < self.buf.len() && (self.buf[begin] <= 0x20) {
                    begin += 1;
                }
                let mut end = begin;
                while end < self.buf.len() && (self.buf[end] > 0x20) {
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return unsafe { str::from_utf8_unchecked(&self.buf[begin..end]) }.parse::<T>();
                } else {
                    self.update_buf();
                }
            }
        }
        pub fn next_line(&mut self) -> String {
            loop {
                let mut begin = self.pos;
                if begin < self.buf.len() && (self.buf[begin] < 0x20) {
                    begin += 1;
                }
                let mut end = begin;
                while end < self.buf.len() && (self.buf[end] >= 0x20) {
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return unsafe { str::from_utf8_unchecked(&self.buf[begin..end]) }.to_string();
                } else {
                    self.update_buf();
                }
            }
        }
        pub fn fast_i64(&mut self) -> i64 {
            loop {
                let mut begin = self.pos;
                while begin < self.buf.len() && (self.buf[begin] <= 0x20) {
                    begin += 1;
                }
                if begin == self.buf.len() {
                    self.update_buf();
                    continue;
                }
                let mut res = 0;
                let (is_positive, mut end) = match self.buf[begin] {
                    b'+' => (true, begin + 1),
                    b'-' => (false, begin + 1),
                    _ => (true, begin),
                };
                while end < self.buf.len() && (self.buf[end] > 0x20) {
                    res = res * 10 + (self.buf[end] as i64 - '0' as i64);
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return if is_positive { res } else { -res };
                } else {
                    self.update_buf();
                }
            }
        }
    }
}

use input_mcr::*;
use std::cmp::*;

use std::collections::BTreeMap;

// [upper_limit, lower_limit), [lower, upper), binary step
#[derive(Debug, Clone)]
pub struct LimittedBinStepRange {
    lower: i64,
    upper: i64,
    lower_limit: i64,
    upper_limit: i64,
}

impl LimittedBinStepRange {
    pub fn new(lower: i64, upper: i64, lower_limit: i64, upper_limit: i64) -> LimittedBinStepRange {
        debug_assert!(lower & 1 != upper & 1);
        LimittedBinStepRange {
            lower,
            upper,
            lower_limit,
            upper_limit,
        }
    }
    pub fn fix(&mut self) {
        if self.lower < self.lower_limit {
            self.lower += (self.lower_limit - self.lower + 1) / 2 * 2;
        }
        if self.upper > self.upper_limit {
            self.upper -= (self.upper - self.upper_limit + 1) / 2 * 2;
        }
    }
    pub fn add1(&mut self) {
        self.lower += 1;
        self.upper += 1;
        self.fix();
    }
    pub fn sub1(&mut self) {
        self.lower -= 1;
        self.upper -= 1;
        self.fix();
    }
    pub fn add1sub1(&mut self) {
        self.lower -= 1;
        self.upper += 1;
        self.fix();
    }
    pub fn add(&self, x: i64) -> LimittedBinStepRange {
        let mut res = self.clone();
        res.lower += x;
        res.upper += x;
        res.fix();
        res
    }
    pub fn unite(s: LimittedBinStepRange, t: LimittedBinStepRange) -> LimittedBinStepRange {
        debug_assert!(s.lower_limit == t.lower_limit);
        debug_assert!(s.upper_limit == t.upper_limit);
        let mut res = LimittedBinStepRange::new(
            min(s.lower, t.lower),
            max(s.upper, t.upper),
            s.lower_limit,
            s.upper_limit,
        );
        res.fix();
        res
    }
    pub fn is_empty(&self) -> bool {
        !(self.lower < self.upper)
    }
}

fn main() {
    input! {
        s: chars,
    }

    let f = |upper_limit: i64| {
        let mut lower_limit = -((1i64 << 21) - 1);
        'b: for d in (0..21).rev() {
            let t = lower_limit + (1 << d);
            let mut range = LimittedBinStepRange::new(0, 1, t, upper_limit);
            //// eprintln!("range = {:?}", range);
            for &c in &s {
                if c == '0' {
                    range.add1();
                }
                if c == '1' {
                    range.sub1();
                }
                if c == '?' {
                    range.add1sub1();
                }
                //// eprintln!("range = {:?}", range);
                if range.is_empty() {
                    continue 'b;
                }
            }
            //// eprintln!("t = {}, range = {:?}", t, range);
            if !range.is_empty() {
                lower_limit = t;
            }
        }
        //// eprintln!("upper_limit = {}, lower_limit = {}", upper_limit, lower_limit);
        upper_limit - lower_limit
    };

    let mut upper_limit_0 = 1;
    let mut upper_limit_3 = 1i64 << 21;
    let mut memo = BTreeMap::new();
    while upper_limit_3 - upper_limit_0 > 3 {
        let upper_limit_1 = (upper_limit_0 * 2 + upper_limit_3) / 3;
        let upper_limit_2 = (upper_limit_0 + upper_limit_3 * 2) / 3;
        let f_upper_limit_1 = *memo.entry(upper_limit_1).or_insert(f(upper_limit_1));
        let f_upper_limit_2 = *memo.entry(upper_limit_2).or_insert(f(upper_limit_2));
        if f_upper_limit_1 < f_upper_limit_2 {
            upper_limit_3 = upper_limit_2;
        } else {
            upper_limit_0 = upper_limit_1;
        }
    }
    let mut res = 1i64 << 30;
    for i in upper_limit_0..upper_limit_3 + 1 {
        let t = f(i);
        // eprintln!("f({}) = {}", i, t);
        res = min(res, t);
    }
    println!("{}", res - 1);
}
